import SwiftUI

/// Tappable profile mention chip. Renders `@displayName` and, when an avatar
/// URL is available, a small circular avatar alongside the name. Falls back to
/// a deterministic identicon color block when no URL is provided.
///
/// Depends on `swiftui/content-core` for the `NostrContentRenderer` environment
/// (colors + callbacks).
public struct NostrMentionChip: View {
    public var pubkey: String
    public var displayName: String?
    public var avatarUrl: URL?
    public var showsAvatar: Bool

    @Environment(\.nostrContentRenderer) private var renderer

    public init(
        pubkey: String,
        displayName: String? = nil,
        avatarUrl: URL? = nil,
        showsAvatar: Bool = true
    ) {
        self.pubkey = pubkey
        self.displayName = displayName
        self.avatarUrl = avatarUrl
        self.showsAvatar = showsAvatar
    }

    public var body: some View {
        Button {
            renderer.callbacks.onMentionTap(pubkey)
        } label: {
            HStack(spacing: 4) {
                if showsAvatar {
                    avatar
                }
                Text("@\(label)")
                    .foregroundStyle(renderer.mentionColor)
                    .fontWeight(.semibold)
                    .lineLimit(1)
            }
        }
        .buttonStyle(.plain)
        .accessibilityLabel("Mention of \(label)")
    }

    private var label: String {
        if let displayName, !displayName.isEmpty {
            return displayName
        }
        return shortPubkey(pubkey)
    }

    @ViewBuilder
    private var avatar: some View {
        if let avatarUrl {
            NostrImageView(url: avatarUrl)
                .frame(width: 16, height: 16)
                .clipShape(Circle())
        } else {
            fallback
        }
    }

    private var fallback: some View {
        NostrIdenticon.identiconView(forPubkey: pubkey, size: 16)
            .clipShape(Circle())
    }

    private func shortPubkey(_ value: String) -> String {
        guard value.count > 12 else { return value }
        return "\(value.prefix(8))…\(value.suffix(4))"
    }
}

import SwiftUI

/// Photo-style grid layout for an ordered list of image URLs.
///
/// Layout rules:
///   • 1 image  — full-width
///   • 2 images — side-by-side, equal halves
///   • 3 images — one large on the left, two stacked on the right
///   • 4+       — 2×2 grid; last visible cell carries a "+N more" overlay
///
/// Tapping a cell calls `NostrContentCallbacks.onImageTap` from the
/// `NostrContentRenderer` environment. Apps that want different routing can
/// provide a `tapHandler` closure to override the environment callback.
///
/// Depends on `swiftui/content-core`.
public struct NostrMediaGrid: View {
    public var imageUrls: [URL]
    public var aspectRatio: CGFloat
    public var cornerRadius: CGFloat
    public var tapHandler: ((URL) -> Void)?

    @Environment(\.nostrContentRenderer) private var renderer

    public init(
        imageUrls: [URL],
        aspectRatio: CGFloat = 16.0 / 9.0,
        cornerRadius: CGFloat = 10,
        tapHandler: ((URL) -> Void)? = nil
    ) {
        self.imageUrls = imageUrls
        self.aspectRatio = aspectRatio
        self.cornerRadius = cornerRadius
        self.tapHandler = tapHandler
    }

    public var body: some View {
        switch imageUrls.count {
        case 0:
            EmptyView()
        case 1:
            singleLayout(imageUrls[0])
        case 2:
            doubleLayout(left: imageUrls[0], right: imageUrls[1])
        case 3:
            tripleLayout(primary: imageUrls[0], secondary: imageUrls[1], tertiary: imageUrls[2])
        default:
            quadLayout(imageUrls)
        }
    }

    @ViewBuilder
    private func singleLayout(_ url: URL) -> some View {
        cell(for: url, overlay: nil)
            .aspectRatio(aspectRatio, contentMode: .fit)
    }

    @ViewBuilder
    private func doubleLayout(left: URL, right: URL) -> some View {
        HStack(spacing: 2) {
            cell(for: left, overlay: nil)
            cell(for: right, overlay: nil)
        }
        .aspectRatio(aspectRatio, contentMode: .fit)
    }

    @ViewBuilder
    private func tripleLayout(primary: URL, secondary: URL, tertiary: URL) -> some View {
        HStack(spacing: 2) {
            cell(for: primary, overlay: nil)
            VStack(spacing: 2) {
                cell(for: secondary, overlay: nil)
                cell(for: tertiary, overlay: nil)
            }
        }
        .aspectRatio(aspectRatio, contentMode: .fit)
    }

    @ViewBuilder
    private func quadLayout(_ urls: [URL]) -> some View {
        let visible = Array(urls.prefix(4))
        let extra = urls.count - visible.count
        VStack(spacing: 2) {
            HStack(spacing: 2) {
                cell(for: visible[0], overlay: nil)
                cell(for: visible[1], overlay: nil)
            }
            HStack(spacing: 2) {
                cell(for: visible[2], overlay: nil)
                cell(
                    for: visible[3],
                    overlay: extra > 0 ? "+\(extra)" : nil
                )
            }
        }
        .aspectRatio(1, contentMode: .fit)
    }

    @ViewBuilder
    private func cell(for url: URL, overlay: String?) -> some View {
        Button {
            (tapHandler ?? renderer.callbacks.onImageTap)(url)
        } label: {
            // Loading + failure handling lives in the renderer-installed
            // `imageLoader` (see swiftui/content-core). Apps wiring Kingfisher
            // or Nuke get all grid cells routed through their loader without
            // changing the grid layout.
            NostrImageView(url: url)
                .frame(maxWidth: .infinity, maxHeight: .infinity)
                .clipped()
                .overlay {
                    if let overlay {
                        ZStack {
                            Color.black.opacity(0.45)
                            Text(overlay)
                                .font(.title3.weight(.semibold))
                                .foregroundStyle(.white)
                        }
                    }
                }
                .clipShape(RoundedRectangle(cornerRadius: cornerRadius))
        }
        .buttonStyle(.plain)
        .accessibilityLabel("Image")
    }
}

import AVKit
import SwiftUI
import UIKit

/// SwiftUI renderer for a `ContentTreeWire`. Walks `tree.roots`, flattens the
/// arena into block-level groups via `nostrContentGroups`, and renders each
/// block (paragraph/heading/media/code/list/quote/rule/image/event-ref/
/// placeholder) with SwiftUI `Text` concatenation for inline runs.
///
/// Data injection contract:
///   • Theming + tap callbacks come from `NostrContentRenderer` in the
///     SwiftUI environment (see `swiftui/content-core`).
///   • Mention display labels are provided by the app via `mentionLabel`.
///   • Embedded events (`nostr:nevent…` / `nostr:naddr…`) render through the
///     kind-dispatch registry (ADR-0034): the app binds an `EmbedEnvelopeSource`
///     + `EventRefResolverProtocol` + `NostrKindRegistry` via
///     `.embedEnvelopeSource(...)` and `eventRefView` dispatches through
///     `EmbeddedEvent`. With no host bound,
///     `EmbeddedEvent` still renders a loading placeholder via the default
///     registry — there is no separate quote-card fallback.
public struct NostrContentView: View {
    public var tree: ContentTreeWire
    public var font: Font
    public var mentionLabel: (NostrWireUri) -> String
    /// Highlight overlays to paint on the body. Each decoration's `quote` is
    /// matched against the rendered plain text and painted with its colour;
    /// taps route to `renderer.callbacks.onDecorationTap`. Empty (the default)
    /// keeps the fast `Text`-concatenation path.
    public var decorations: [NostrContentDecoration]
    /// Opt-in body text selection. When `true`, paragraph/heading runs become
    /// selectable and the selection edit menu gains a "Highlight" action that
    /// fires `renderer.callbacks.onTextSelected(quote, context)`. Off by
    /// default so non-article surfaces keep the lightweight `Text` path.
    public var selectionEnabled: Bool

    // Non-private so the article-mode extension (NostrContentArticleView,
    // NostrContentAttributed) in the same module can read theming + callbacks.
    @Environment(\.nostrContentRenderer) var renderer
    @Environment(\.embedEnvelopeSource) private var embedEnvelopeSource
    @Environment(\.embedEventRefResolver) private var embedEventRefResolver
    @Environment(\.nostrKindRegistry) private var nostrKindRegistry

    public init(
        tree: ContentTreeWire,
        font: Font = .body,
        mentionLabel: @escaping (NostrWireUri) -> String = NostrContentView.defaultMentionLabel,
        decorations: [NostrContentDecoration] = [],
        selectionEnabled: Bool = false
    ) {
        self.tree = tree
        self.font = font
        self.mentionLabel = mentionLabel
        self.decorations = decorations
        self.selectionEnabled = selectionEnabled
    }

    public var body: some View {
        let groups = nostrContentGroups(tree)
        if groups.isEmpty {
            EmptyView()
        } else if articleMode {
            // Footnote-definition paragraphs (`[^1]: …`) are rendered once, by
            // `footnoteSection`. Suppress the originals from the normal loop so
            // the body shows each definition exactly once and the marker
            // scrolls to the single rendered block.
            let bodyGroups = groups.filter { !isFootnoteDefinitionGroup($0) }
            ScrollViewReader { proxy in
                VStack(alignment: .leading, spacing: 8) {
                    ForEach(Array(bodyGroups.enumerated()), id: \.offset) { _, group in
                        groupView(group, proxy: proxy)
                    }
                    footnoteSection(proxy: proxy)
                }
            }
        } else {
            VStack(alignment: .leading, spacing: 8) {
                ForEach(Array(groups.enumerated()), id: \.offset) { _, group in
                    groupView(group, proxy: nil)
                }
            }
        }
    }

    // MARK: - Group dispatch

    @ViewBuilder
    private func groupView(_ group: NostrContentGroup, proxy: ScrollViewProxy?) -> some View {
        switch group {
        case .inline(let level, let children):
            inlineGroup(level: level, children: children, proxy: proxy)
        case .media(let urls, let kind):
            mediaGroup(urls: urls, kind: kind)
        case .eventRef(let uri):
            eventRefView(uri)
        case .codeBlock(let info, let body):
            codeBlockView(info: info, body: body)
        case .blockQuote(let children):
            blockQuoteView(children: children)
        case .list(let orderedStart, let items):
            listView(orderedStart: orderedStart, items: items)
        case .rule:
            ruleView
        case .image(let alt, let title, let src):
            imageBlockView(alt: alt, title: title, src: src)
        case .placeholder(let reason):
            placeholderChip(reason: reason)
        }
    }

    @ViewBuilder
    private func inlineGroup(level: NostrContentInlineLevel, children: [UInt32], proxy: ScrollViewProxy?) -> some View {
        if articleMode {
            articleInlineGroup(level: level, children: children, proxy: proxy)
        } else {
            let concatenated = children.reduce(Text("")) { acc, child in
                acc + inlineText(child)
            }
            switch level {
            case .paragraph:
                concatenated
                    .font(font)
                    .foregroundStyle(renderer.textColor)
                    .fixedSize(horizontal: false, vertical: true)
            case .heading(let lvl):
                concatenated
                    .font(headingFont(for: lvl))
                    .foregroundStyle(renderer.textColor)
                    .fixedSize(horizontal: false, vertical: true)
            }
        }
    }

    // MARK: - Inline text concatenation

    /// Convert one arena node into a `Text` value that can be `+`-concatenated
    /// with neighbouring runs. Recursive children (emphasis/strong/link/heading
    /// /paragraph) are walked here so the whole inline subtree collapses to a
    /// single `Text`.
    public func inlineText(_ index: UInt32) -> Text {
        if index == nostrContentNewlineSentinel { return Text("\n") }
        guard let node = tree.node(at: index) else { return Text("") }
        switch node {
        case .text(let value):
            return Text(value)
        case .mention(let uri):
            return Text("@\(mentionLabel(uri))")
                .foregroundStyle(renderer.mentionColor)
                .bold()
        case .eventRef(let uri):
            return Text("↩ \(shortEntity(uri.primaryId))")
                .foregroundStyle(renderer.linkColor)
                .bold()
        case .hashtag(let tag):
            return Text("#\(tag)")
                .foregroundStyle(renderer.hashtagColor)
                .bold()
        case .url(let value):
            return Text(value).foregroundStyle(renderer.linkColor)
        case .emoji(let shortcode, _):
            // Apps fill `renderer.emojiImages` from kind:0 / NIP-30 tag data
            // and the inline run renders the image directly. Empty dict
            // (the default) falls back to the literal `:shortcode:` text so
            // unwired apps still get a readable surface.
            if let img = renderer.emojiImages[shortcode] {
                return Text(Image(uiImage: img))
            }
            return Text(":\(shortcode):")
        case .invoice:
            return Text("⚡ invoice").foregroundStyle(renderer.linkColor)
        case .emphasis(let children):
            return children.reduce(Text("")) { $0 + inlineText($1).italic() }
        case .strong(let children):
            return children.reduce(Text("")) { $0 + inlineText($1).bold() }
        case .inlineCode(let value):
            return Text(value).font(.system(.body, design: .monospaced))
        case .link(let children, let href):
            let label = children.reduce(Text("")) { $0 + inlineText($1) }
            if let href, !href.isEmpty {
                return label
                    .foregroundStyle(renderer.linkColor)
                    .underline()
            }
            return label
        case .image(let alt, _, _):
            return Text(alt.isEmpty ? "[image]" : "[\(alt)]")
                .foregroundStyle(renderer.placeholderColor)
        case .softBreak:
            return Text(" ")
        case .hardBreak:
            return Text("\n")
        case .paragraph(let children),
             .heading(_, let children),
             .blockQuote(let children):
            return children.reduce(Text("")) { $0 + inlineText($1) }
        case .list, .codeBlock, .rule, .media, .placeholder:
            // Block-level — should never appear inside an inline reduce. Emit
            // nothing rather than break the text concatenation.
            return Text("")
        }
    }

    // MARK: - Block builders

    @ViewBuilder
    private func mediaGroup(urls: [String], kind: NostrMediaKind) -> some View {
        switch kind {
        case .image:
            let parsed = urls.compactMap(URL.init(string:))
            if !parsed.isEmpty {
                NostrMediaGrid(imageUrls: parsed)
            }
        case .video:
            // Inline playback via `AVKit.VideoPlayer` so video media nodes
            // render with native scrub / fullscreen controls. Audio stays on
            // the compact link-style row (no waveform UI in v1).
            if let first = urls.first.flatMap(URL.init(string:)) {
                VideoPlayer(player: AVPlayer(url: first))
                    .aspectRatio(16.0 / 9.0, contentMode: .fit)
                    .clipShape(RoundedRectangle(cornerRadius: 10))
            }
        case .audio:
            if let first = urls.first.flatMap(URL.init(string:)) {
                mediaRow(first, systemImage: "speaker.wave.2.fill")
            }
        }
    }

    private func mediaRow(_ url: URL, systemImage: String) -> some View {
        Button {
            renderer.callbacks.onLinkTap(url)
        } label: {
            HStack(spacing: 10) {
                Image(systemName: systemImage)
                    .font(.title2)
                    .foregroundStyle(renderer.linkColor)
                Text(url.lastPathComponent)
                    .font(.caption.monospaced())
                    .foregroundStyle(renderer.secondaryTextColor)
                    .lineLimit(1)
                Spacer(minLength: 0)
            }
            .padding(12)
            .frame(maxWidth: .infinity)
            .background(renderer.codeBackgroundColor, in: RoundedRectangle(cornerRadius: 8))
        }
        .buttonStyle(.plain)
    }

    private func eventRefView(_ uri: NostrWireUri) -> some View {
        // Kind-dispatch path (ADR-0034 / F-CR-04). `EmbeddedEvent` owns the
        // resolve/release lifecycle via `task(id:)` + `onDisappear`; the registry
        // picks the renderer for the resolved projection. The view always
        // renders even if the host hasn't resolved the envelope yet (loading
        // placeholder via `EmbedChromeContainer`). With no registry bound, the
        // built-in defaults render.
        EmbeddedEvent(
            uri: uri.uri,
            envelope: embedEnvelopeSource?.envelopeForPrimaryID(uri.primaryId)
                ?? embedEnvelopeSource?.envelopeForURI(uri.uri),
            registry: nostrKindRegistry ?? NostrKindRegistry.makeDefault(),
            eventRefResolver: embedEventRefResolver
        )
    }

    private func codeBlockView(info: String?, body: String) -> some View {
        VStack(alignment: .leading, spacing: 4) {
            if let info, !info.isEmpty {
                Text(info)
                    .font(.caption2.monospaced())
                    .foregroundStyle(renderer.secondaryTextColor)
            }
            Text(body)
                .font(.system(.callout, design: .monospaced))
                .foregroundStyle(renderer.textColor)
                .frame(maxWidth: .infinity, alignment: .leading)
        }
        .padding(10)
        .background(renderer.codeBackgroundColor, in: RoundedRectangle(cornerRadius: 6))
    }

    private func blockQuoteView(children: [UInt32]) -> some View {
        let text = children.reduce(Text("")) { $0 + inlineText($1) }
        return HStack(spacing: 10) {
            Rectangle()
                .fill(renderer.quoteBorderColor)
                .frame(width: 3)
            text
                .font(font.italic())
                .foregroundStyle(renderer.secondaryTextColor)
                .frame(maxWidth: .infinity, alignment: .leading)
        }
        .padding(.vertical, 4)
        .frame(maxWidth: .infinity, alignment: .leading)
    }

    @ViewBuilder
    private func listView(orderedStart: UInt64?, items: [[UInt32]]) -> some View {
        VStack(alignment: .leading, spacing: 4) {
            ForEach(Array(items.enumerated()), id: \.offset) { offset, children in
                HStack(alignment: .firstTextBaseline, spacing: 8) {
                    Text(marker(orderedStart: orderedStart, offset: offset))
                        .font(font)
                        .foregroundStyle(renderer.secondaryTextColor)
                    children.reduce(Text("")) { $0 + inlineText($1) }
                        .font(font)
                        .foregroundStyle(renderer.textColor)
                        .frame(maxWidth: .infinity, alignment: .leading)
                }
            }
        }
    }

    private func marker(orderedStart: UInt64?, offset: Int) -> String {
        if let orderedStart {
            return "\(orderedStart + UInt64(offset))."
        }
        return "•"
    }

    private var ruleView: some View {
        Rectangle()
            .fill(renderer.quoteBorderColor)
            .frame(height: 1)
            .padding(.vertical, 4)
    }

    private func imageBlockView(alt: String, title: String?, src: String?) -> some View {
        if let src, let url = URL(string: src) {
            return AnyView(
                NostrMediaGrid(imageUrls: [url])
                    .accessibilityLabel(title ?? alt)
            )
        }
        return AnyView(
            Text(alt.isEmpty ? "[image]" : "[\(alt)]")
                .font(.caption)
                .foregroundStyle(renderer.placeholderColor)
        )
    }

    private func placeholderChip(reason: NostrWirePlaceholderReason) -> some View {
        let label: String
        let icon: String
        switch reason {
        case .depthLimit:
            label = "Nested content collapsed"
            icon = "chevron.down.square"
        case .unresolvedUri:
            label = "Unresolved reference"
            icon = "questionmark.square.dashed"
        }
        return HStack(spacing: 6) {
            Image(systemName: icon)
                .foregroundStyle(renderer.placeholderColor)
            Text(label)
                .font(.caption.weight(.semibold))
                .foregroundStyle(renderer.placeholderColor)
        }
        .padding(.horizontal, 8)
        .padding(.vertical, 4)
        .background(renderer.codeBackgroundColor, in: Capsule())
    }

    // MARK: - Defaults / helpers

    public nonisolated static func defaultMentionLabel(_ uri: NostrWireUri) -> String {
        let value = uri.primaryId
        guard value.count > 12 else { return value }
        return "\(value.prefix(8))…\(value.suffix(4))"
    }

    private func headingFont(for level: UInt8) -> Font {
        switch level {
        case 1: return .largeTitle.weight(.bold)
        case 2: return .title.weight(.bold)
        case 3: return .title2.weight(.semibold)
        case 4: return .title3.weight(.semibold)
        case 5: return .headline
        default: return .subheadline.weight(.semibold)
        }
    }

    private func shortEntity(_ value: String) -> String {
        guard value.count > 12 else { return value }
        return "\(value.prefix(8))…\(value.suffix(4))"
    }
}

import SwiftUI

/// Block-level group produced by walking the roots of a `ContentTreeWire`.
/// `NostrContentView` consumes these in order; the grouping logic exists in a
/// separate file so the renderer view itself stays focused on layout.
public enum NostrContentGroup: Equatable {
    /// Inline runs that should be concatenated with `Text + Text`. The
    /// `[UInt32]` values are node indices; `.init(UInt32.max)` is a sentinel
    /// trailing newline used to separate adjacent paragraphs/headings.
    case inline(level: NostrContentInlineLevel, children: [UInt32])
    case media(urls: [String], kind: NostrMediaKind)
    case eventRef(NostrWireUri)
    case codeBlock(info: String?, body: String)
    case blockQuote(children: [UInt32])
    case list(orderedStart: UInt64?, items: [[UInt32]])
    case rule
    case image(alt: String, title: String?, src: String?)
    case placeholder(reason: NostrWirePlaceholderReason)
}

/// Display level for inline-text groups; lets the renderer pick paragraph vs
/// heading typography without re-walking the arena.
public enum NostrContentInlineLevel: Equatable {
    case paragraph
    case heading(level: UInt8)
}

/// Sentinel index used to inject a trailing newline between contiguous inline
/// groups (paragraph/heading). Index `UInt32.max` cannot reference a real
/// arena slot — the bounds check in `node(at:)` rejects it — so renderers can
/// safely treat it as a newline marker.
public let nostrContentNewlineSentinel: UInt32 = .max

/// Flatten the document into the block-level sequence consumed by
/// `NostrContentView`.
public func nostrContentGroups(_ tree: ContentTreeWire) -> [NostrContentGroup] {
    var groups: [NostrContentGroup] = []
    var pendingChildren: [UInt32] = []
    var pendingLevel: NostrContentInlineLevel = .paragraph

    func flush() {
        if !pendingChildren.isEmpty {
            groups.append(.inline(level: pendingLevel, children: pendingChildren))
            pendingChildren = []
            pendingLevel = .paragraph
        }
    }

    func appendInline(level: NostrContentInlineLevel, children: [UInt32]) {
        // Different inline-block levels can't share a paragraph; flush first.
        if !pendingChildren.isEmpty, pendingLevel != level {
            flush()
        }
        pendingLevel = level

        let startCount = pendingChildren.count
        for child in children {
            guard let childNode = tree.node(at: child) else { continue }
            if case .eventRef(let uri) = childNode {
                flush()
                groups.append(.eventRef(uri))
            } else {
                pendingChildren.append(child)
            }
        }
        if pendingChildren.count > startCount {
            pendingChildren.append(nostrContentNewlineSentinel)
        }
    }

    for root in tree.roots {
        guard let node = tree.node(at: root) else { continue }
        switch node {
        case .paragraph(let children):
            appendInline(level: .paragraph, children: children)
        case .heading(let level, let children):
            flush()
            appendInline(level: .heading(level: level), children: children)
            flush()
        case .media(let urls, let kind):
            flush()
            groups.append(.media(urls: urls, kind: kind))
        case .eventRef(let uri):
            flush()
            groups.append(.eventRef(uri))
        case .codeBlock(let info, let body):
            flush()
            groups.append(.codeBlock(info: info, body: body))
        case .blockQuote(let children):
            flush()
            groups.append(.blockQuote(children: children))
        case .list(let orderedStart, let items):
            flush()
            groups.append(.list(orderedStart: orderedStart, items: items))
        case .rule:
            flush()
            groups.append(.rule)
        case .image(let alt, let title, let src):
            flush()
            groups.append(.image(alt: alt, title: title, src: src))
        case .placeholder(let reason):
            flush()
            groups.append(.placeholder(reason: reason))
        default:
            // Bare inline node sitting at the root (e.g. plain text with no
            // surrounding paragraph). Treat it as a one-child paragraph.
            appendInline(level: .paragraph, children: [root])
        }
    }
    flush()
    return groups
}

import SwiftUI

// MARK: - Decoration model (range overlays)

/// Opaque identity for a body decoration (typically a NIP-84 highlight event
/// id). The renderer carries it through `onDecorationTap` so the app can open
/// the underlying highlight without the renderer knowing what it is.
public struct NostrContentDecorationId: Hashable, Sendable {
    public let raw: String
    public init(_ raw: String) { self.raw = raw }
}

/// A highlight overlay to render on the article body. The renderer locates
/// `quote` as a substring of the reconstructed plain-text body and paints the
/// matching range with `color`. Expressing the range as the *quoted text*
/// (rather than a byte offset) matches the NIP-84 data model — a kind:9802
/// highlight stores the quoted text — so no positional metadata is needed from
/// the content tree.
///
/// `quote` is matched case-sensitively against the body's visible text. If the
/// same quote appears more than once, every occurrence is decorated; apps that
/// need single-occurrence disambiguation should pass a longer surrounding span.
public struct NostrContentDecoration: Identifiable, Equatable, Sendable {
    public let id: NostrContentDecorationId
    public let quote: String
    public let color: Color

    public init(id: NostrContentDecorationId, quote: String, color: Color) {
        self.id = id
        self.quote = quote
        self.color = color
    }

    public init(id: String, quote: String, color: Color) {
        self.init(id: NostrContentDecorationId(id), quote: quote, color: color)
    }
}

// MARK: - Footnotes

/// A footnote parsed out of the body text. NIP-23 article bodies carry footnote
/// markers as Commonmark `[^label]` references plus a matching `[^label]: …`
/// definition; the Rust content tree models these as plain text (no dedicated
/// footnote node), so the renderer recovers them at render time from the text
/// runs. `marker` is the display marker (1-based ordinal), `label` the source
/// label, and `body` the definition text.
public struct NostrContentFootnote: Identifiable, Equatable, Sendable {
    public let id: String
    public let label: String
    public let marker: Int
    public let body: String

    public init(id: String, label: String, marker: Int, body: String) {
        self.id = id
        self.label = label
        self.marker = marker
        self.body = body
    }
}

// MARK: - Plain-text reconstruction

/// Reconstruct the visible plain text of one inline run subtree, in render
/// order. Used both for the `onTextSelected` context payload and for locating
/// decoration / footnote substrings. Mirrors the visible glyphs the renderer
/// emits for the same nodes (mentions render as `@label`, hashtags as `#tag`,
/// etc.) so a selection range maps back onto the source text predictably.
public func nostrContentPlainText(
    _ tree: ContentTreeWire,
    children: [UInt32],
    mentionLabel: (NostrWireUri) -> String
) -> String {
    var out = ""
    func walk(_ index: UInt32) {
        if index == nostrContentNewlineSentinel {
            out += "\n"
            return
        }
        guard let node = tree.node(at: index) else { return }
        switch node {
        case .text(let value): out += value
        case .mention(let uri): out += "@\(mentionLabel(uri))"
        case .eventRef(let uri): out += uri.primaryId
        case .hashtag(let tag): out += "#\(tag)"
        case .url(let value): out += value
        case .emoji(let shortcode, _): out += ":\(shortcode):"
        case .inlineCode(let value): out += value
        case .emphasis(let kids), .strong(let kids):
            kids.forEach(walk)
        case .link(let kids, _):
            kids.forEach(walk)
        case .paragraph(let kids), .heading(_, let kids), .blockQuote(let kids):
            kids.forEach(walk)
        case .image(let alt, _, _):
            out += alt.isEmpty ? "[image]" : "[\(alt)]"
        case .softBreak: out += " "
        case .hardBreak: out += "\n"
        case .invoice, .list, .codeBlock, .rule, .media, .placeholder:
            break
        }
    }
    children.forEach(walk)
    return out
}

// MARK: - Footnote extraction

/// Extract footnote definitions (`[^label]: body`) from the document's text
/// nodes, numbering them in first-reference order. Returns the footnotes keyed
/// for lookup plus an ordinal map from source label → display marker.
public func nostrContentFootnotes(_ tree: ContentTreeWire) -> [NostrContentFootnote] {
    // 1. Collect every label referenced via `[^label]` across all text nodes,
    //    in document order, to assign stable 1-based markers.
    var order: [String] = []
    var seen = Set<String>()
    var definitions: [String: String] = [:]

    for node in tree.nodes {
        guard case .text(let value) = node else { continue }
        for label in footnoteReferences(in: value) where !seen.contains(label) {
            seen.insert(label)
            order.append(label)
        }
        for (label, body) in footnoteDefinitions(in: value) {
            definitions[label] = body
        }
    }

    // A label only becomes a real footnote if it has a definition.
    var result: [NostrContentFootnote] = []
    var marker = 0
    for label in order {
        guard let body = definitions[label] else { continue }
        marker += 1
        result.append(
            NostrContentFootnote(id: label, label: label, marker: marker, body: body)
        )
    }
    return result
}

/// Inline `[^label]` references in a string, excluding definition lines
/// (`[^label]:`), in order.
func footnoteReferences(in value: String) -> [String] {
    var labels: [String] = []
    let scalars = Array(value)
    var i = 0
    while i < scalars.count {
        if scalars[i] == "[", i + 1 < scalars.count, scalars[i + 1] == "^" {
            var j = i + 2
            var label = ""
            while j < scalars.count, scalars[j] != "]" {
                label.append(scalars[j])
                j += 1
            }
            // Require a closing `]`, a non-empty label, and that this is a
            // reference (not a `[^x]:` definition).
            if j < scalars.count, scalars[j] == "]", !label.isEmpty {
                let isDefinition = j + 1 < scalars.count && scalars[j + 1] == ":"
                if !isDefinition { labels.append(label) }
                i = j + 1
                continue
            }
        }
        i += 1
    }
    return labels
}

/// `[^label]: body` definitions in a string.
func footnoteDefinitions(in value: String) -> [(String, String)] {
    var defs: [(String, String)] = []
    for line in value.split(separator: "\n", omittingEmptySubsequences: false) {
        let trimmed = line.trimmingCharacters(in: .whitespaces)
        guard trimmed.hasPrefix("[^"),
              let close = trimmed.range(of: "]:")
        else { continue }
        let label = String(trimmed[trimmed.index(trimmed.startIndex, offsetBy: 2)..<close.lowerBound])
        let body = String(trimmed[close.upperBound...]).trimmingCharacters(in: .whitespaces)
        if !label.isEmpty { defs.append((label, body)) }
    }
    return defs
}

import SwiftUI
import UIKit

/// Custom URL schemes the article-mode renderer uses to make decoration and
/// footnote ranges tappable inside `NostrSelectableText`. The view layer maps a
/// tapped link back to the originating decoration id / footnote label.
public enum NostrContentLink {
    public static let decorationScheme = "nmp-decoration"
    public static let footnoteScheme = "nmp-footnote"

    public static func decoration(_ id: NostrContentDecorationId) -> URL? {
        guard let encoded = id.raw.addingPercentEncoding(withAllowedCharacters: .urlHostAllowed)
        else { return nil }
        return URL(string: "\(decorationScheme)://\(encoded)")
    }

    public static func footnote(_ label: String) -> URL? {
        guard let encoded = label.addingPercentEncoding(withAllowedCharacters: .urlHostAllowed)
        else { return nil }
        return URL(string: "\(footnoteScheme)://\(encoded)")
    }

    /// Decode a tapped link back into either a decoration id or a footnote
    /// label. Returns `nil` for any other URL (those route to `onLinkTap`).
    public static func decode(_ url: URL) -> Decoded? {
        guard let host = url.host?.removingPercentEncoding else { return nil }
        switch url.scheme {
        case decorationScheme: return .decoration(NostrContentDecorationId(host))
        case footnoteScheme: return .footnote(host)
        default: return nil
        }
    }

    public enum Decoded {
        case decoration(NostrContentDecorationId)
        case footnote(String)
    }
}

/// `NSAttributedString` inline builder for *article mode* (selection /
/// decorations / footnotes). SwiftUI `Text` concatenation can't paint a
/// background over an arbitrary range or expose selection, so article surfaces
/// render their inline runs through a `UITextView` (`NostrSelectableText`),
/// which needs an `NSAttributedString`. The non-article fast path keeps using
/// `inlineText` (concatenated `Text`).
extension NostrContentView {
    func articleAttributed(
        _ children: [UInt32],
        baseFont: UIFont,
        decorations: [NostrContentDecoration],
        footnotes: [NostrContentFootnote]
    ) -> NSAttributedString {
        let out = NSMutableAttributedString()
        for child in children {
            out.append(articleNode(child, baseFont: baseFont))
        }
        // Default text colour for any run that didn't set its own.
        out.enumerateAttribute(.foregroundColor, in: NSRange(location: 0, length: out.length)) { value, range, _ in
            if value == nil {
                out.addAttribute(.foregroundColor, value: uiColor(renderer.textColor), range: range)
            }
        }
        applyFootnoteMarkers(to: out, footnotes: footnotes)
        applyDecorations(to: out, decorations: decorations)
        return out
    }

    private func uiColor(_ color: Color) -> UIColor { UIColor(color) }

    private func articleNode(_ index: UInt32, baseFont: UIFont) -> NSAttributedString {
        if index == nostrContentNewlineSentinel { return NSAttributedString(string: "\n") }
        guard let node = tree.node(at: index) else { return NSAttributedString() }
        func styled(_ string: String, _ attrs: [NSAttributedString.Key: Any] = [:]) -> NSAttributedString {
            var merged: [NSAttributedString.Key: Any] = [.font: baseFont]
            merged.merge(attrs) { _, new in new }
            return NSAttributedString(string: string, attributes: merged)
        }
        switch node {
        case .text(let value):
            return styled(value)
        case .mention(let uri):
            return styled("@\(mentionLabel(uri))", [
                .foregroundColor: uiColor(renderer.mentionColor),
                .font: bold(baseFont),
            ])
        case .eventRef(let uri):
            return styled(uri.primaryId, [.foregroundColor: uiColor(renderer.linkColor)])
        case .hashtag(let tag):
            return styled("#\(tag)", [
                .foregroundColor: uiColor(renderer.hashtagColor),
                .font: bold(baseFont),
            ])
        case .url(let value):
            return styled(value, [.foregroundColor: uiColor(renderer.linkColor)])
        case .emoji(let shortcode, _):
            return styled(":\(shortcode):")
        case .inlineCode(let value):
            return styled(value, [.font: UIFont.monospacedSystemFont(ofSize: baseFont.pointSize, weight: .regular)])
        case .emphasis(let kids):
            return reduce(kids, baseFont: italic(baseFont))
        case .strong(let kids):
            return reduce(kids, baseFont: bold(baseFont))
        case .link(let kids, let href):
            let inner = reduce(kids, baseFont: baseFont)
            if let href, !href.isEmpty, let url = URL(string: href) {
                let m = NSMutableAttributedString(attributedString: inner)
                let full = NSRange(location: 0, length: m.length)
                m.addAttributes([
                    .foregroundColor: uiColor(renderer.linkColor),
                    .underlineStyle: NSUnderlineStyle.single.rawValue,
                    .link: url,
                ], range: full)
                return m
            }
            return inner
        case .paragraph(let kids), .heading(_, let kids), .blockQuote(let kids):
            return reduce(kids, baseFont: baseFont)
        case .image(let alt, _, _):
            return styled(alt.isEmpty ? "[image]" : "[\(alt)]", [
                .foregroundColor: uiColor(renderer.placeholderColor),
            ])
        case .softBreak:
            return styled(" ")
        case .hardBreak:
            return styled("\n")
        case .invoice, .list, .codeBlock, .rule, .media, .placeholder:
            return NSAttributedString()
        }
    }

    private func reduce(_ kids: [UInt32], baseFont: UIFont) -> NSAttributedString {
        let out = NSMutableAttributedString()
        for kid in kids { out.append(articleNode(kid, baseFont: baseFont)) }
        return out
    }

    private func applyDecorations(
        to out: NSMutableAttributedString,
        decorations: [NostrContentDecoration]
    ) {
        guard !decorations.isEmpty else { return }
        let plain = out.string as NSString
        for decoration in decorations where !decoration.quote.isEmpty {
            var searchRange = NSRange(location: 0, length: plain.length)
            while searchRange.location < plain.length {
                let found = plain.range(of: decoration.quote, options: [], range: searchRange)
                if found.location == NSNotFound { break }
                out.addAttribute(.backgroundColor, value: uiColor(decoration.color), range: found)
                if let link = NostrContentLink.decoration(decoration.id) {
                    out.addAttribute(.link, value: link, range: found)
                }
                let next = found.location + max(found.length, 1)
                searchRange = NSRange(location: next, length: plain.length - next)
            }
        }
    }

    /// Turn `[^label]` reference markers into superscript, tappable ordinal
    /// markers (`¹`, `²`, …). Only labels that resolved to a footnote are
    /// replaced; the rest stay as literal text.
    private func applyFootnoteMarkers(
        to out: NSMutableAttributedString,
        footnotes: [NostrContentFootnote]
    ) {
        guard !footnotes.isEmpty else { return }
        // `nostrContentFootnotes` already dedupes by label; `uniquingKeysWith`
        // keeps this crash-proof even if a duplicate label ever slips through.
        let byLabel = Dictionary(footnotes.map { ($0.label, $0) }, uniquingKeysWith: { first, _ in first })
        // Replace from the end so earlier ranges stay valid as we mutate.
        let plain = out.string as NSString
        var replacements: [(NSRange, NostrContentFootnote)] = []
        var search = NSRange(location: 0, length: plain.length)
        while search.location < plain.length {
            let open = plain.range(of: "[^", options: [], range: search)
            if open.location == NSNotFound { break }
            let afterOpen = open.location + open.length
            let closeSearch = NSRange(location: afterOpen, length: plain.length - afterOpen)
            let close = plain.range(of: "]", options: [], range: closeSearch)
            if close.location == NSNotFound { break }
            let labelRange = NSRange(location: afterOpen, length: close.location - afterOpen)
            let label = plain.substring(with: labelRange)
            let isDef = close.location + 1 < plain.length
                && plain.substring(with: NSRange(location: close.location + 1, length: 1)) == ":"
            if !isDef, let fn = byLabel[label] {
                let full = NSRange(location: open.location, length: close.location + 1 - open.location)
                replacements.append((full, fn))
            }
            search = NSRange(location: close.location + 1, length: plain.length - close.location - 1)
        }
        for (range, fn) in replacements.reversed() {
            let marker = NSMutableAttributedString(string: " \(fn.marker)")
            marker.addAttributes([
                .foregroundColor: uiColor(renderer.linkColor),
                .baselineOffset: 5,
            ], range: NSRange(location: 0, length: marker.length))
            if let link = NostrContentLink.footnote(fn.label) {
                marker.addAttribute(.link, value: link, range: NSRange(location: 0, length: marker.length))
            }
            out.replaceCharacters(in: range, with: marker)
        }
    }

    private func bold(_ font: UIFont) -> UIFont {
        guard let d = font.fontDescriptor.withSymbolicTraits(font.fontDescriptor.symbolicTraits.union(.traitBold)) else { return font }
        return UIFont(descriptor: d, size: font.pointSize)
    }

    private func italic(_ font: UIFont) -> UIFont {
        guard let d = font.fontDescriptor.withSymbolicTraits(font.fontDescriptor.symbolicTraits.union(.traitItalic)) else { return font }
        return UIFont(descriptor: d, size: font.pointSize)
    }
}

import SwiftUI
import UIKit

/// Article-mode rendering for `NostrContentView`: the selection / decoration /
/// footnote path. Kept in its own extension so the core renderer stays focused
/// on the default `Text`-concatenation surface. Article mode activates when the
/// host opts into selection, supplies decorations, or the body carries
/// footnotes — see `articleMode`.
extension NostrContentView {
    /// Footnotes recovered from the body text (`[^label]` + `[^label]:`). The
    /// Rust content tree has no footnote node, so these are parsed from the
    /// shipped text at render time.
    var footnotes: [NostrContentFootnote] { nostrContentFootnotes(tree) }

    /// Article mode turns on the `UITextView`-backed inline path (selection /
    /// decoration overlays / tappable footnote markers). Off, the renderer uses
    /// pure SwiftUI `Text` concatenation, unchanged.
    var articleMode: Bool {
        selectionEnabled || !decorations.isEmpty || !footnotes.isEmpty
    }

    func footnoteAnchorId(_ label: String) -> String { "nmp-footnote-\(label)" }

    /// True when an inline group is *only* footnote definitions (`[^label]: …`)
    /// for labels that resolved to a real footnote. Such groups are suppressed
    /// from the body loop because `footnoteSection` renders them — rendering
    /// them in both places would duplicate every definition and split the
    /// scroll-to anchor. Groups that mix a definition with other prose are kept
    /// (we only drop pure-definition paragraphs); an empty group is not a
    /// definition.
    func isFootnoteDefinitionGroup(_ group: NostrContentGroup) -> Bool {
        guard case .inline(_, let children) = group else { return false }
        let text = nostrContentPlainText(tree, children: children, mentionLabel: mentionLabel)
            .trimmingCharacters(in: .whitespacesAndNewlines)
        guard !text.isEmpty else { return false }
        let knownLabels = Set(footnotes.map(\.label))
        // Every non-empty line must be a definition for a known footnote label.
        let lines = text.split(separator: "\n", omittingEmptySubsequences: true)
        guard !lines.isEmpty else { return false }
        for line in lines {
            let defs = footnoteDefinitions(in: String(line))
            guard defs.count == 1, let (label, _) = defs.first, knownLabels.contains(label) else {
                return false
            }
        }
        return true
    }

    /// Route a tapped link from `NostrSelectableText`: decoration → app
    /// callback, footnote → scroll, anything else (real `http(s)` links) →
    /// `onLinkTap`.
    func handleArticleLink(_ url: URL, proxy: ScrollViewProxy?) {
        switch NostrContentLink.decode(url) {
        case .decoration(let id):
            renderer.callbacks.onDecorationTap(id)
        case .footnote(let label):
            withAnimation { proxy?.scrollTo(footnoteAnchorId(label), anchor: .top) }
        case .none:
            if let scheme = url.scheme, scheme == "http" || scheme == "https" {
                renderer.callbacks.onLinkTap(url)
            }
        }
    }

    /// Article-mode inline run: rendered through `NostrSelectableText` (a
    /// `UITextView`) so selection, decoration overlays, and footnote markers
    /// all work. The selection menu reports `(quote, context)` and decoration /
    /// footnote link taps route through `handleArticleLink`.
    @ViewBuilder
    func articleInlineGroup(level: NostrContentInlineLevel, children: [UInt32], proxy: ScrollViewProxy?) -> some View {
        let baseFont = articleBaseFont(for: level)
        let attributed = articleAttributed(
            children,
            baseFont: baseFont,
            decorations: decorations,
            footnotes: footnotes
        )
        NostrSelectableText(
            attributed: attributed,
            onSelect: { quote, context in
                renderer.callbacks.onTextSelected(quote, context)
            },
            onLink: { url in handleArticleLink(url, proxy: proxy) }
        )
        .frame(maxWidth: .infinity, alignment: .leading)
    }

    private func articleBaseFont(for level: NostrContentInlineLevel) -> UIFont {
        switch level {
        case .paragraph: return UIFont.preferredFont(forTextStyle: .body)
        case .heading(let lvl): return headingUIFont(for: lvl)
        }
    }

    private func headingUIFont(for level: UInt8) -> UIFont {
        let style: UIFont.TextStyle
        switch level {
        case 1: style = .largeTitle
        case 2: style = .title1
        case 3: style = .title2
        case 4: style = .title3
        case 5: style = .headline
        default: style = .subheadline
        }
        let base = UIFont.preferredFont(forTextStyle: style)
        guard let d = base.fontDescriptor.withSymbolicTraits(.traitBold) else { return base }
        return UIFont(descriptor: d, size: base.pointSize)
    }

    /// Footnote definitions rendered at the foot of the article, each with a
    /// stable scroll anchor so a `[^n]` marker tap can jump to it via the
    /// `ScrollViewReader` in `body`.
    @ViewBuilder
    func footnoteSection(proxy: ScrollViewProxy) -> some View {
        if !footnotes.isEmpty {
            VStack(alignment: .leading, spacing: 8) {
                Rectangle()
                    .fill(renderer.quoteBorderColor)
                    .frame(height: 1)
                    .padding(.vertical, 4)
                ForEach(footnotes) { footnote in
                    HStack(alignment: .firstTextBaseline, spacing: 8) {
                        Text("\(footnote.marker).")
                            .font(.caption.weight(.semibold))
                            .foregroundStyle(renderer.linkColor)
                        Text(footnote.body)
                            .font(.callout)
                            .foregroundStyle(renderer.secondaryTextColor)
                            .fixedSize(horizontal: false, vertical: true)
                    }
                    .id(footnoteAnchorId(footnote.label))
                }
            }
            .padding(.top, 4)
        }
    }
}

import SwiftUI
import UIKit

/// A `UITextView`-backed inline paragraph that adds the three article-reading
/// capabilities SwiftUI `Text` cannot express:
///
///   1. **Selection → highlight.** A custom "Highlight" edit-menu action over
///      the user's selection reports `(quote, context)` back to the app via
///      `onSelect`, where `context` is the full paragraph the selection sits
///      inside. Standard Copy/Look-Up/etc. stay available.
///   2. **Range overlays.** Decorations and footnote markers arrive pre-painted
///      in the `attributed` string (background colour + a custom-scheme link),
///      so tapping a decorated range fires `onLink`.
///   3. **Footnote navigation.** Footnote markers are likewise link ranges;
///      `onLink` routes the tap to the scroll-to-footnote handler.
///
/// Only paragraph/heading inline runs route through this; block-level content
/// (media, embeds, code, lists) stays in native SwiftUI. The representable is
/// self-sizing: it disables its own scrolling and reports an intrinsic height
/// to SwiftUI's layout.
struct NostrSelectableText: UIViewRepresentable {
    let attributed: NSAttributedString
    /// `(quote, context)` — the selected substring and the full paragraph text.
    let onSelect: (String, String) -> Void
    /// Tap on a decoration / footnote link range; carries the link URL.
    let onLink: (URL) -> Void

    func makeUIView(context: Context) -> SelfSizingTextView {
        let view = SelfSizingTextView()
        view.isEditable = false
        view.isScrollEnabled = false
        view.isSelectable = true
        view.backgroundColor = .clear
        view.textContainerInset = .zero
        view.textContainer.lineFragmentPadding = 0
        view.adjustsFontForContentSizeCategory = true
        view.delegate = context.coordinator
        view.setContentCompressionResistancePriority(.required, for: .vertical)
        view.setContentHuggingPriority(.required, for: .vertical)
        context.coordinator.attach(view)
        return view
    }

    func updateUIView(_ view: SelfSizingTextView, context: Context) {
        context.coordinator.parent = self
        if view.attributedText != attributed {
            view.attributedText = attributed
            view.invalidateIntrinsicContentSize()
        }
    }

    func makeCoordinator() -> Coordinator { Coordinator(self) }

    final class Coordinator: NSObject, UITextViewDelegate {
        var parent: NostrSelectableText
        private weak var view: UITextView?

        init(_ parent: NostrSelectableText) { self.parent = parent }

        func attach(_ view: UITextView) { self.view = view }

        // Route decoration / footnote link taps (custom-scheme URLs) to the app
        // instead of letting UIKit try to open them. iOS 17+ text-item API.
        func textView(
            _ textView: UITextView,
            primaryActionFor textItem: UITextItem,
            defaultAction: UIAction
        ) -> UIAction? {
            if case .link(let url) = textItem.content {
                let parent = self.parent
                return UIAction { _ in parent.onLink(url) }
            }
            return defaultAction
        }

        // Inject a "Highlight" action into the selection edit menu (iOS 16+).
        func textView(
            _ textView: UITextView,
            editMenuForTextIn range: NSRange,
            suggestedActions: [UIMenuElement]
        ) -> UIMenu? {
            guard range.length > 0,
                  let text = textView.text,
                  let swiftRange = Range(range, in: text)
            else {
                return UIMenu(children: suggestedActions)
            }
            let quote = String(text[swiftRange])
            let context = text
            let highlight = UIAction(
                title: "Highlight",
                image: UIImage(systemName: "highlighter")
            ) { [weak self] _ in
                self?.parent.onSelect(quote, context)
            }
            return UIMenu(children: [highlight] + suggestedActions)
        }
    }
}

/// `UITextView` subclass that reports its laid-out height as its intrinsic
/// content size so it composes inside a SwiftUI `VStack` without an explicit
/// frame. Width comes from the SwiftUI parent; height is derived from it.
final class SelfSizingTextView: UITextView {
    override var intrinsicContentSize: CGSize {
        let width = bounds.width > 0 ? bounds.width : UIView.layoutFittingExpandedSize.width
        let fitting = sizeThatFits(CGSize(width: width, height: .greatestFiniteMagnitude))
        return CGSize(width: UIView.noIntrinsicMetric, height: ceil(fitting.height))
    }

    override func layoutSubviews() {
        super.layoutSubviews()
        if bounds.width != lastWidth {
            lastWidth = bounds.width
            invalidateIntrinsicContentSize()
        }
    }

    private var lastWidth: CGFloat = 0
}

