import Foundation

/// Wire type for a Nostr user profile, decoded from the `nmp-profile`
/// projection emitted by the kernel.
///
/// `npub` and `npubShort` are always Rust-formatted — never reformat
/// them in Swift (aim.md §6.9).
public struct ProfileWire: Codable, Equatable, Sendable {
    public let pubkey: String
    public let displayName: String?
    public let about: String?
    public let pictureUrl: String?
    public let nip05: String?
    /// Full bech32 `npub1…` string. Use for copy / share.
    public let npub: String
    /// Rust-truncated npub (e.g. `npub1abcd…wxyz`). Display only.
    public let npubShort: String

    public init(
        pubkey: String,
        displayName: String? = nil,
        about: String? = nil,
        pictureUrl: String? = nil,
        nip05: String? = nil,
        npub: String,
        npubShort: String
    ) {
        self.pubkey = pubkey
        self.displayName = displayName
        self.about = about
        self.pictureUrl = pictureUrl
        self.nip05 = nip05
        self.npub = npub
        self.npubShort = npubShort
    }

    /// Stable display label: `displayName` if set, else `npubShort`.
    public var display: String {
        if let name = displayName, !name.isEmpty { return name }
        return npubShort
    }

    /// Parsed avatar URL; `nil` when no picture is set or URL is empty.
    public var avatarURL: URL? {
        guard let str = pictureUrl, !str.isEmpty else { return nil }
        return URL(string: str)
    }
}

import SwiftUI

/// Host bridge for profile projections owned by the NMP kernel.
///
/// Registry components call this bridge with stable Nostr references. The app
/// supplies one platform adapter that maps `resolveProfileRef` to the kernel's
/// profile `resolve_ref` path and reads the current row from `refs.profile`.
/// Components own when to resolve, release, and re-read the projection.
@MainActor
public protocol NostrProfileHost: AnyObject {
    func profile(forPubkey pubkey: String) -> ProfileWire?
    func resolveProfileRef(pubkey: String, consumerID: String)
    func releaseProfileRef(pubkey: String, consumerID: String)
}

private struct NostrProfileHostKey: EnvironmentKey {
    nonisolated(unsafe)
    static let defaultValue: NostrProfileHost? = nil
}

public extension EnvironmentValues {
    var nostrProfileHost: NostrProfileHost? {
        get { self[NostrProfileHostKey.self] }
        set { self[NostrProfileHostKey.self] = newValue }
    }
}

import SwiftUI
import Foundation

/// Circular avatar for a Nostr pubkey. Shows the profile picture when the
/// host projection has it; falls back to a deterministic identicon derived
/// from `pubkey`.
///
/// Replace `AsyncImage` with your own image cache (Kingfisher, Nuke, etc.)
/// if you already have one — the identicon fallback is self-contained.
///
/// Depends on `swiftui/user-avatar` for `ProfileWire` and `NostrProfileHost`.
public struct NostrAvatar: View {
    @Environment(\.nostrProfileHost) private var profileHost

    public let pubkey: String
    public let pictureUrl: URL?
    public let size: CGFloat
    public let consumerID: String?
    @State private var generatedConsumerID: String
    @State private var claimedPubkey: String?

    public init(
        pubkey: String,
        pictureUrl: URL? = nil,
        size: CGFloat = 40,
        consumerID: String? = nil
    ) {
        self.pubkey = pubkey
        self.pictureUrl = pictureUrl
        self.size = size
        self.consumerID = consumerID
        self._generatedConsumerID = State(
            initialValue: consumerID ?? "nostr-avatar.\(UUID().uuidString)"
        )
        self._claimedPubkey = State(initialValue: nil)
    }

    public init(profile: ProfileWire, size: CGFloat = 40) {
        self.pubkey = profile.pubkey
        self.pictureUrl = profile.avatarURL
        self.size = size
        self.consumerID = nil
        self._generatedConsumerID = State(
            initialValue: "nostr-avatar.static.\(UUID().uuidString)"
        )
        self._claimedPubkey = State(initialValue: nil)
    }

    public var body: some View {
        let url = pictureUrl ?? profileHost?.profile(forPubkey: pubkey)?.avatarURL

        Group {
            if let url {
                AsyncImage(url: url) { phase in
                    switch phase {
                    case .success(let image):
                        image.resizable().scaledToFill()
                    default:
                        identicon
                    }
                }
            } else {
                identicon
            }
        }
        .frame(width: size, height: size)
        .clipShape(Circle())
        .accessibilityHidden(true)
        .task(id: pubkey) {
            await MainActor.run {
                if let claimedPubkey, claimedPubkey != pubkey {
                    profileHost?.releaseProfile(
                        pubkey: claimedPubkey,
                        consumerID: generatedConsumerID
                    )
                }
                claimedPubkey = pubkey
                profileHost?.claimProfile(pubkey: pubkey, consumerID: generatedConsumerID)
            }
        }
        .onDisappear {
            if let claimedPubkey {
                profileHost?.releaseProfile(pubkey: claimedPubkey, consumerID: generatedConsumerID)
                self.claimedPubkey = nil
            }
        }
    }

    private var identicon: some View {
        ZStack {
            Circle().fill(NostrIdenticon.color(forPubkey: pubkey))
            Text(NostrIdenticon.initials(forPubkey: pubkey))
                .font(.system(size: size * 0.35, weight: .semibold))
                .foregroundStyle(.white)
        }
    }
}

// MARK: - Identicon

/// Deterministic color + initials from a raw pubkey hex string.
/// Edit `palette` to match your app's brand palette.
public enum NostrIdenticon {
    private static let palette: [Color] = [
        Color(red: 0.36, green: 0.20, blue: 0.81),
        Color(red: 0.10, green: 0.53, blue: 0.82),
        Color(red: 0.13, green: 0.55, blue: 0.42),
        Color(red: 0.82, green: 0.33, blue: 0.18),
        Color(red: 0.76, green: 0.15, blue: 0.45),
        Color(red: 0.20, green: 0.20, blue: 0.20),
    ]

    public static func color(forPubkey pubkey: String) -> Color {
        let sum = pubkey.utf8.prefix(4).reduce(0) { $0 + Int($1) }
        return palette[sum % palette.count]
    }

    public static func initials(forPubkey pubkey: String) -> String {
        guard pubkey.count >= 2 else { return "?" }
        return String(pubkey.prefix(2)).uppercased()
    }
}

import SwiftUI

/// Inline display-name text for a Nostr profile.
///
/// Two construction modes:
///   • `NostrProfileName(profile:)` — caller already holds a `ProfileWire`.
///     Resolves the profile's pubkey on mount so the name stays fresh (mirrors
///     `NostrAvatar`), reads `profile.display`.
///   • `NostrProfileName(pubkey:)` — self-resolving. The component owns the
///     responsibility of resolving the kind:0 it needs: on mount it resolves
///     the profile through the `NostrProfileHost`, reads the `refs.profile` projection
///     reactively, and releases on disappear. This mirrors `NostrAvatar`'s
///     resolve/release lifecycle exactly, so any standalone name render anywhere
///     triggers resolution (resolve-only invariant — every author-displaying
///     surface must self-resolve).
///
/// Display always comes from a Rust-formatted source — `displayName` when set,
/// else `npubShort` (always Rust-formatted — aim.md §6.9). Until the host has
/// any profile for the pubkey, the self-resolving variant renders nothing rather
/// than synthesize a Swift-side abbreviation.
///
/// Depends on `swiftui/user-avatar` for `ProfileWire` and `NostrProfileHost`.
public struct NostrProfileName: View {
    @Environment(\.nostrProfileHost) private var profileHost

    /// Static profile supplied directly by the caller. `nil` when constructed
    /// in the self-resolving `pubkey:` mode.
    private let staticProfile: ProfileWire?
    /// Pubkey to resolve (also the static profile's pubkey in static mode).
    private let pubkey: String
    public var font: Font
    public var color: Color

    @State private var generatedConsumerID: String
    @State private var activePubkey: String?

    /// Static variant: render the supplied `ProfileWire`. Resolves its pubkey on
    /// mount so the name stays fresh.
    public init(
        profile: ProfileWire,
        font: Font = .headline,
        color: Color = .primary
    ) {
        self.staticProfile = profile
        self.pubkey = profile.pubkey
        self.font = font
        self.color = color
        self._generatedConsumerID = State(
            initialValue: "nostr-profile-name.\(UUID().uuidString)")
        self._activePubkey = State(initialValue: nil)
    }

    /// Self-resolving variant: resolve the kind:0 for `pubkey` through the host,
    /// read the resolved profile reactively, release on disappear.
    public init(
        pubkey: String,
        font: Font = .body,
        color: Color = .primary,
        consumerID: String? = nil
    ) {
        self.staticProfile = nil
        self.pubkey = pubkey
        self.font = font
        self.color = color
        self._generatedConsumerID = State(
            initialValue: consumerID ?? "nostr-profile-name.\(UUID().uuidString)")
        self._activePubkey = State(initialValue: nil)
    }

    public var body: some View {
        let resolved = staticProfile ?? profileHost?.profile(forPubkey: pubkey)
        return Group {
            if let resolved {
                label(for: resolved)
            } else {
                // No kind:0 yet, and no Rust-formatted npubShort available.
                // Render nothing rather than a Swift-side abbreviation.
                EmptyView()
            }
        }
        .task(id: pubkey) {
            await MainActor.run {
                if let activePubkey, activePubkey != pubkey {
                    profileHost?.releaseProfileRef(
                        pubkey: activePubkey, consumerID: generatedConsumerID)
                }
                activePubkey = pubkey
                profileHost?.resolveProfileRef(pubkey: pubkey, consumerID: generatedConsumerID)
            }
        }
        .onDisappear {
            if let activePubkey {
                profileHost?.releaseProfileRef(
                    pubkey: activePubkey, consumerID: generatedConsumerID)
                self.activePubkey = nil
            }
        }
    }

    private func label(for profile: ProfileWire) -> some View {
        Text(profile.display)
            .font(font)
            .foregroundStyle(color)
            .lineLimit(1)
            .accessibilityLabel("Display name: \(profile.display)")
    }
}

