import androidx.compose.ui.semantics.semantics
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.unit.Dp
import androidx.compose.ui.unit.dp
import coil.compose.SubcomposeAsyncImage

@Composable
public fun NostrMediaGrid(
    imageUrls: List<String>,
    modifier: Modifier = Modifier,
    aspectRatio: Float = 16f / 9f,
    cornerRadius: Dp = 10.dp,
    tapHandler: ((String) -> Unit)? = null,
) {
    if (imageUrls.isEmpty()) return
    val renderer = LocalNostrContentRenderer.current
    val onTap: (String) -> Unit = tapHandler ?: renderer.callbacks.onImageTap

    when (imageUrls.size) {
        1 -> SingleLayout(
            url = imageUrls[0],
            aspectRatio = aspectRatio,
            cornerRadius = cornerRadius,
            onTap = onTap,
            modifier = modifier,
        )
        2 -> DoubleLayout(
            left = imageUrls[0],
            right = imageUrls[1],
            aspectRatio = aspectRatio,
            cornerRadius = cornerRadius,
            onTap = onTap,
            modifier = modifier,
        )
        3 -> TripleLayout(
            primary = imageUrls[0],
            secondary = imageUrls[1],
            tertiary = imageUrls[2],
            aspectRatio = aspectRatio,
            cornerRadius = cornerRadius,
            onTap = onTap,
            modifier = modifier,
        )
        else -> QuadLayout(
            urls = imageUrls,
            cornerRadius = cornerRadius,
            onTap = onTap,
            modifier = modifier,
        )
    }
}

@Composable
private fun SingleLayout(
    url: String,
    aspectRatio: Float,
    cornerRadius: Dp,
    onTap: (String) -> Unit,
    modifier: Modifier,
) {
    MediaCell(
        url = url,
        overlay = null,
        cornerRadius = cornerRadius,
        onTap = onTap,
        modifier = modifier
            .fillMaxWidth()
            .aspectRatio(aspectRatio),
    )
}

@Composable
private fun DoubleLayout(
    left: String,
    right: String,
    aspectRatio: Float,
    cornerRadius: Dp,
    onTap: (String) -> Unit,
    modifier: Modifier,
) {
    Row(
        horizontalArrangement = Arrangement.spacedBy(2.dp),
        modifier = modifier
            .fillMaxWidth()
            .aspectRatio(aspectRatio),
    ) {
        MediaCell(
            url = left,
            overlay = null,
            cornerRadius = cornerRadius,
            onTap = onTap,
            modifier = Modifier.weight(1f).fillMaxSize(),
        )
        MediaCell(
            url = right,
            overlay = null,
            cornerRadius = cornerRadius,
            onTap = onTap,
            modifier = Modifier.weight(1f).fillMaxSize(),
        )
    }
}

@Composable
private fun TripleLayout(
    primary: String,
    secondary: String,
    tertiary: String,
    aspectRatio: Float,
    cornerRadius: Dp,
    onTap: (String) -> Unit,
    modifier: Modifier,
) {
    Row(
        horizontalArrangement = Arrangement.spacedBy(2.dp),
        modifier = modifier
            .fillMaxWidth()
            .aspectRatio(aspectRatio),
    ) {
        MediaCell(
            url = primary,
            overlay = null,
            cornerRadius = cornerRadius,
            onTap = onTap,
            modifier = Modifier.weight(1f).fillMaxSize(),
        )
        Column(
            verticalArrangement = Arrangement.spacedBy(2.dp),
            modifier = Modifier.weight(1f).fillMaxSize(),
        ) {
            MediaCell(
                url = secondary,
                overlay = null,
                cornerRadius = cornerRadius,
                onTap = onTap,
                modifier = Modifier.weight(1f).fillMaxSize(),
            )
            MediaCell(
                url = tertiary,
                overlay = null,
                cornerRadius = cornerRadius,
                onTap = onTap,
                modifier = Modifier.weight(1f).fillMaxSize(),
            )
        }
    }
}

@Composable
private fun QuadLayout(
    urls: List<String>,
    cornerRadius: Dp,
    onTap: (String) -> Unit,
    modifier: Modifier,
) {
    val visible = urls.take(4)
    val extra = urls.size - visible.size
    Column(
        verticalArrangement = Arrangement.spacedBy(2.dp),
        modifier = modifier
            .fillMaxWidth()
            .aspectRatio(1f),
    ) {
        Row(
            horizontalArrangement = Arrangement.spacedBy(2.dp),
            modifier = Modifier.weight(1f).fillMaxWidth(),
        ) {
            MediaCell(
                url = visible[0],
                overlay = null,
                cornerRadius = cornerRadius,
                onTap = onTap,
                modifier = Modifier.weight(1f).fillMaxSize(),
            )
            MediaCell(
                url = visible[1],
                overlay = null,
                cornerRadius = cornerRadius,
                onTap = onTap,
                modifier = Modifier.weight(1f).fillMaxSize(),
            )
        }
        Row(
            horizontalArrangement = Arrangement.spacedBy(2.dp),
            modifier = Modifier.weight(1f).fillMaxWidth(),
        ) {
            MediaCell(
                url = visible[2],
                overlay = null,
                cornerRadius = cornerRadius,
                onTap = onTap,
                modifier = Modifier.weight(1f).fillMaxSize(),
            )
            MediaCell(
                url = visible[3],
                overlay = if (extra > 0) "+$extra" else null,
                cornerRadius = cornerRadius,
                onTap = onTap,
                modifier = Modifier.weight(1f).fillMaxSize(),
            )
        }
    }
}

@Composable
private fun MediaCell(
    url: String,
    overlay: String?,
    cornerRadius: Dp,
    onTap: (String) -> Unit,
    modifier: Modifier = Modifier,
) {
    val renderer = LocalNostrContentRenderer.current
    Box(
        modifier = modifier
            .clip(RoundedCornerShape(cornerRadius))
            .clickable { onTap(url) }
            .semantics { contentDescription = "Image" },
    ) {
        SubcomposeAsyncImage(
            model = url,
            contentDescription = null,
            contentScale = ContentScale.Crop,
            loading = {
                Box(
                    contentAlignment = Alignment.Center,
                    modifier = Modifier
                        .fillMaxSize()
                        .background(renderer.codeBackgroundColor),
                ) {
                    CircularProgressIndicator(strokeWidth = 2.dp)
                }
            },
            error = {
                Box(
                    contentAlignment = Alignment.Center,
                    modifier = Modifier
                        .fillMaxSize()
                        .background(renderer.codeBackgroundColor),
                ) {
                    Icon(
                        imageVector = Icons.Filled.BrokenImage,
                        contentDescription = null,
                        tint = renderer.placeholderColor,
                    )
                }
            },
            modifier = Modifier.fillMaxSize(),
        )
        if (overlay != null) {
            Box(
                contentAlignment = Alignment.Center,
                modifier = Modifier
                    .fillMaxSize()
                    .background(Color.Black.copy(alpha = 0.45f)),
            ) {
                Text(
                    text = overlay,
                    color = Color.White,
                    fontWeight = FontWeight.SemiBold,
                )
            }
        }
    }
}

// Requires: kotlinx.serialization. Kotlin 1.9+.
//
// Kotlin kotlinx.serialization mirror of the Rust
// `nmp_content::embed_projection::EmbeddedEventEnvelope` / `EmbedKindProjection`.
//
// The Rust enum is serialized with `#[serde(tag = "variant", content = "data",
// rename_all = "camelCase")]`, but the typed NEMB sidecar decoder on Android
// populates exactly one variant field (`shortNote` / `article` / …). This file
// models that already-decoded shape: the dispatch decision is a `when` over
// which variant is non-null. No protocol parsing happens here — the kernel
// resolved the event into a typed projection before it reached this layer.
//
// Compose mirror of the SwiftUI `EmbedKindProjection.swift`.

package nmp.content

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable

/**
 * Kind-dispatched embed projection — exactly one variant is non-null, selected
 * by the kernel's resolver from the `kind` discriminant. Mirrors the SwiftUI
 * `EmbedKindProjection` enum. DECODE-ONLY: no resolution logic lives here.
 */
@Serializable
public data class EmbedKindProjection(
    @SerialName("short_note") val shortNote: ShortNoteProjection? = null,
    val article: ArticleProjection? = null,
    val highlight: HighlightProjection? = null,
    val profile: ProfileProjection? = null,
    val unknown: UnknownProjection? = null,
)

/** kind:1 short text note projection. */
@Serializable
public data class ShortNoteProjection(
    val id: String = "",
    @SerialName("author_pubkey") val authorPubkey: String = "",
    @SerialName("author_display_name") val authorDisplayName: String? = null,
    @SerialName("author_picture_url") val authorPictureUrl: String? = null,
    @SerialName("created_at") val createdAt: Long = 0,
    /** Plain-text fallback for the content body. */
    val content: String = "",
    @SerialName("media_urls") val mediaUrls: List<String> = emptyList(),
)

/** kind:30023 long-form article projection (NIP-23). */
@Serializable
public data class ArticleProjection(
    val id: String = "",
    @SerialName("author_pubkey") val authorPubkey: String = "",
    @SerialName("author_display_name") val authorDisplayName: String? = null,
    @SerialName("author_picture_url") val authorPictureUrl: String? = null,
    @SerialName("created_at") val createdAt: Long = 0,
    val title: String? = null,
    val summary: String? = null,
    @SerialName("hero_image_url") val heroImageUrl: String? = null,
    @SerialName("d_tag") val dTag: String = "",
    val content: String = "",
)

/** kind:9802 highlight projection (NIP-84). */
@Serializable
public data class HighlightProjection(
    val id: String = "",
    @SerialName("author_pubkey") val authorPubkey: String = "",
    @SerialName("author_display_name") val authorDisplayName: String? = null,
    @SerialName("created_at") val createdAt: Long = 0,
    @SerialName("highlighted_text") val highlightedText: String = "",
    @SerialName("source_event_id") val sourceEventId: String? = null,
    @SerialName("source_event_addr") val sourceEventAddr: String? = null,
    @SerialName("source_url") val sourceUrl: String? = null,
    val context: String? = null,
)

/** kind:0 profile metadata projection. */
@Serializable
public data class ProfileProjection(
    val pubkey: String = "",
    @SerialName("display_name") val displayName: String? = null,
    @SerialName("picture_url") val pictureUrl: String? = null,
    val about: String? = null,
    val nip05: String? = null,
    val lud16: String? = null,
    @SerialName("banner_url") val bannerUrl: String? = null,
