package org.nmp.registry

import android.content.Intent
import android.net.Uri

// ── Amber / NIP-55 encoding + decoding ────────────────────────────────────────
//
// Everything in this file is the mechanical translation between the
// nmp-signer-iface wire shapes (ExternalSignerWire.kt) and Amber's NIP-55
// Intent contract. Pure top-level functions where possible so unit tests
// exercise the SAME logic the bridge executes (no test-side copies).
//
// Vendored with ExternalSignerCapabilityBridge.kt + ExternalSignerWire.kt as
// one unit (ADR-0048 Stage 2): byte-identical copies except the package line,
// see VendorDriftGateTest.

/**
 * THE transport-selection rule (ADR-0048 D2) — a mechanical consequence of
 * fields Rust set on the request, never host policy (D7):
 *
 * | Condition | Mechanism |
 * |---|---|
 * | `forceInteractive == true` | Intent |
 * | `signerPackage` known AND method's permission in `grantedPermissions` | ContentResolver |
 * | otherwise | Intent |
 */
internal fun shouldUseContentResolver(request: ExternalSignerRequest): Boolean =
    !request.forceInteractive &&
        request.signerPackage != null &&
        request.grantedPermissions.any { p -> p.kind.startsWith(request.method.toPermissionKind()) }

/**
 * Select the reply value from an Amber `RESULT_OK` Intent (Stage-4 emulator
 * finding #3).
 *
 * Amber's `IntentUtils.sendResult` sets:
 *  - `result` extra — signature hex for `sign_event`; pubkey for
 *    `get_public_key`; ciphertext/plaintext for encrypt/decrypt.
 *  - `event` extra — the full signed-event JSON (`sign_event` replies).
 *
 * Rust's `parse_signed_event_response` verifies id + schnorr signature on the
 * COMPLETE event, so `sign_event` must return the `event` extra; everything
 * else uses `result`. Mechanical extra selection, not policy (D7).
 */
internal fun selectAmberResultValue(
    method: String,
    eventExtra: String?,
    resultExtra: String?,
): String? = if (method == "sign_event") {
    eventExtra.takeUnless { it.isNullOrBlank() } ?: resultExtra
} else {
    resultExtra
}

/**
 * Build the Amber-specific permissions JSON array from a `Nip55Permission` list.
 *
 * Our internal format: `kind` is a combined string like `"sign_event:1"`,
 * `"nip44_encrypt"`, etc.
 *
 * Amber expects: `[{"type":"sign_event","kind":1},{"type":"nip44_encrypt"}]`
 * — a separate `type` (method) and optional integer `kind` (event kind).
 */
internal fun buildAmberPermissionsJsonInternal(permissions: List<Nip55Permission>): String {
    val sb = StringBuilder("[")
    permissions.forEachIndexed { idx, perm ->
        if (idx > 0) sb.append(",")
        val combined = perm.kind
        val colonIdx = combined.indexOf(':')
        if (colonIdx >= 0) {
            // "sign_event:1" → type="sign_event", kind=1
            val typePart = combined.substring(0, colonIdx)
            val kindPart = combined.substring(colonIdx + 1).toIntOrNull()
            if (kindPart != null) {
                sb.append("""{"type":"$typePart","kind":$kindPart}""")
            } else {
                sb.append("""{"type":"$typePart"}""")
            }
        } else {
            // "nip44_encrypt" → type="nip44_encrypt"
            sb.append("""{"type":"$combined"}""")
        }
    }
    sb.append("]")
    return sb.toString()
}

/**
 * Build the NIP-55 Intent for one `ExternalSignerRequest`.
 *
 * Amber (v6.x) reads the method PAYLOAD from the Intent data URI
 * (`nostrsigner:<url-encoded payload>`) and every other parameter from
 * Intent extras. Amber's SignerActivity branches on the presence of
 * `Browser.EXTRA_APPLICATION_ID` to choose between URI-query parsing and
 * extras parsing. We do NOT set that extra, so extras-based parsing is
 * always used.
 *
 * Amber requires:
 *   intent.data             = nostrsigner:<Uri.encode(payload)>
 *                             (unsigned-event JSON / ciphertext / …;
 *                             bare `nostrsigner:` when payload empty)
 *   extras["type"]          = method tag string (mandatory)
 *   extras["id"]            = caller request id (echoed in the reply)
 *   extras["returnType"]    = "signature" | "event" (default: signature)
 *   extras["current_user"]  = current user pubkey hex (if known)
 *   extras["pubkey"]        = counterparty pubkey hex (for encrypt/decrypt)
 *   extras["permissions"]   = JSON array string in Amber format (first call only)
 *
 * Stage-4 fixes (each found by a failing emulator round):
 *  1. `type` must be an extra, not a URI query param — Amber's extras-path
 *     saw no `type` key → SignerType.INVALID → "malformed nostrsigner
 *     request" (get_public_key round).
 *  2. The payload must ride the data URI, not a `payload` extra — Amber's
 *     `IntentUtils.getIntentDataFromIntent` reads
 *     `intent.data.toString().replace("nostrsigner:", "")` and never looks
 *     at a `payload` extra; an empty URI made `getUnsignedEvent("")` throw
 *     → the same "malformed" dialog (sign_event round). `Uri.encode` is
 *     mandatory: Amber URL-decodes only when its `isUrlEncoded` regex
 *     matches, and encoding also keeps JSON `?`/`#` characters from being
 *     parsed as URI structure.
 */
internal fun buildAmberSignerIntent(request: ExternalSignerRequest): Intent {
    val methodTag = request.method.toNostrSignerMethod()
    val uriPayload = if (request.payload.isNotEmpty()) Uri.encode(request.payload) else ""
    val intent = Intent(Intent.ACTION_VIEW, Uri.parse("nostrsigner:$uriPayload"))
    intent.putExtra("type", methodTag)
    intent.putExtra("id", request.correlationId)
    intent.putExtra("returnType", "signature")
    if (request.currentUser != null) {
        intent.putExtra("current_user", request.currentUser)
    }
    if (request.counterparty != null) {
        intent.putExtra("pubkey", request.counterparty)
    }
    if (request.permissions.isNotEmpty()) {
        // Amber expects `[{"type":"sign_event","kind":1},{"type":"nip44_encrypt"}]`.
        // Our `Nip55Permission.kind` is a combined string ("sign_event:1",
        // "nip44_encrypt", etc.) — expand it to the Amber shape.
        intent.putExtra("permissions", buildAmberPermissionsJsonInternal(request.permissions))
    }

    // Include the package hint so Amber auto-routes when multiple
    // nostrsigner-scheme handlers are installed.
    request.signerPackage?.let { pkg -> intent.setPackage(pkg) }
    // testTag for Stage-4 emulator E2E: the correlation_id is passed
    // as an extra so the adb-driven fake can echo it in RESULT_OK.
    intent.putExtra("nmp_correlation_id", request.correlationId)
    return intent
}

// ── Method mapping helpers ────────────────────────────────────────────────────

/**
 * Map the Rust `ExternalSignerMethod` snake_case tag to the NIP-55
 * `nostrsigner:` method name (used in both the Intent URI and as the
 * ContentProvider suffix).
 *
 * Amber uses: `get_public_key`, `sign_event`, `nip44_encrypt`,
 * `nip44_decrypt`, `nip04_encrypt`, `nip04_decrypt`.
 */
internal fun String.toNostrSignerMethod(): String = when (this) {
    "get_public_key" -> "get_public_key"
    "sign_event" -> "sign_event"
    "nip44_encrypt" -> "nip44_encrypt"
    "nip44_decrypt" -> "nip44_decrypt"
    "nip04_encrypt" -> "nip04_encrypt"
    "nip04_decrypt" -> "nip04_decrypt"
    else -> this
}

/**
 * Map a method tag to its corresponding NIP-55 permission kind string
 * used in the permission batch.
 *
 * E.g. `"sign_event"` → `"sign_event:"` (prefix for "sign_event:1" etc.),
 * `"nip44_encrypt"` → `"nip44_encrypt"`.
 */
internal fun String.toPermissionKind(): String = when (this) {
    "sign_event" -> "sign_event:"
    "nip44_encrypt" -> "nip44_encrypt"
    "nip44_decrypt" -> "nip44_decrypt"
    "nip04_encrypt" -> "nip04_encrypt"
    "nip04_decrypt" -> "nip04_decrypt"
    else -> this
}

use serde_json::Value;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ContentTreeWire {
    pub nodes: Vec<WireNode>,
    pub roots: Vec<usize>,
    pub mode: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum WireNode {
    Text(String),
    Mention(WireUri),
    EventRef(WireUri),
    Hashtag(String),
    Url(String),
    Media {
        urls: Vec<String>,
        kind: String,
    },
    Emoji {
        shortcode: String,
        url: Option<String>,
    },
    Invoice {
        invoice: WireInvoice,
    },
    Paragraph {
        children: Vec<usize>,
    },
    Heading {
        level: u8,
        children: Vec<usize>,
    },
    BlockQuote {
        children: Vec<usize>,
    },
    CodeBlock {
        info: Option<String>,
        body: String,
    },
    List {
        ordered_start: Option<u64>,
        items: Vec<Vec<usize>>,
    },
    Rule,
    Emphasis {
        children: Vec<usize>,
    },
    Strong {
        children: Vec<usize>,
    },
    InlineCode(String),
    Link {
        children: Vec<usize>,
        href: Option<String>,
    },
    Image {
        alt: String,
        title: Option<String>,
        src: Option<String>,
    },
    SoftBreak,
    HardBreak,
    Placeholder {
        reason: String,
    },
    Unsupported,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct WireUri {
    pub uri: String,
    pub kind: String,
    pub primary_id: String,
    pub relays: Vec<String>,
    pub author: Option<String>,
    pub event_kind: Option<u64>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct WireInvoice {
    pub kind: String,
    pub value: String,
}

impl ContentTreeWire {
    pub fn from_value(value: &Value) -> Option<Self> {
        let nodes = value
            .get("nodes")?
            .as_array()?
            .iter()
            .map(WireNode::from_value)
            .collect::<Vec<_>>();
        let roots = value
            .get("roots")
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
            .filter_map(|value| value.as_u64().and_then(|idx| usize::try_from(idx).ok()))
            .collect::<Vec<_>>();
        Some(Self {
            nodes,
            roots,
            mode: value
                .get("mode")
                .and_then(Value::as_str)
                .map(str::to_string),
        })
    }

    pub fn mentioned_pubkeys(&self) -> Vec<String> {
        let mut out = std::collections::BTreeSet::new();
        for node in &self.nodes {
            if let WireNode::Mention(uri) = node {
                if is_hex_id_64(&uri.primary_id) {
                    out.insert(uri.primary_id.clone());
                }
            }
        }
        out.into_iter().collect()
    }

    pub fn event_ref_ids(&self) -> Vec<String> {
        let mut out = std::collections::BTreeSet::new();
        for node in &self.nodes {
            if let WireNode::EventRef(uri) = node {
                if uri.kind == "event" && is_hex_id_64(&uri.primary_id) {
                    out.insert(uri.primary_id.clone());
                }
            }
        }
        out.into_iter().collect()
    }

    pub fn media_urls(&self) -> Vec<String> {
        let mut out = Vec::new();
        for node in &self.nodes {
            match node {
                WireNode::Media { urls, .. } => {
                    for url in urls {
                        push_unique(&mut out, url);
                    }
                }
                WireNode::Image { src: Some(src), .. } => push_unique(&mut out, src),
                _ => {}
            }
        }
        out
    }

    pub fn node(&self, index: usize) -> Option<&WireNode> {
        self.nodes.get(index)
    }

    pub fn inline_text(&self, children: &[usize]) -> String {
        children
            .iter()
            .filter_map(|idx| self.node(*idx))
            .map(|node| node.inline_label(self))
            .collect::<Vec<_>>()
            .join("")
    }
}

impl WireNode {
    fn from_value(value: &Value) -> Self {
        match value
            .get("kind")
            .and_then(Value::as_str)
            .unwrap_or_default()
        {
            "text" => Self::Text(string(value, "text")),
            "mention" => uri(value).map_or(Self::Unsupported, Self::Mention),
            "event_ref" => uri(value).map_or(Self::Unsupported, Self::EventRef),
            "hashtag" => Self::Hashtag(string(value, "tag")),
            "url" => Self::Url(string(value, "url")),
            "media" => Self::Media {
                urls: strings(value, "urls"),
                kind: string(value, "media_kind"),
            },
            "emoji" => Self::Emoji {
                shortcode: string(value, "shortcode"),
                url: value.get("url").and_then(Value::as_str).map(str::to_string),
            },
            "invoice" => {
                invoice(value).map_or(Self::Unsupported, |invoice| Self::Invoice { invoice })
            }
            "paragraph" => Self::Paragraph {
                children: indices(value, "children"),
            },
            "heading" => Self::Heading {
                level: value.get("level").and_then(Value::as_u64).unwrap_or(1) as u8,
                children: indices(value, "children"),
            },
            "block_quote" => Self::BlockQuote {
                children: indices(value, "children"),
            },
            "code_block" => Self::CodeBlock {
                info: value
                    .get("info")
                    .and_then(Value::as_str)
                    .map(str::to_string),
                body: string(value, "body"),
            },
            "list" => Self::List {
                ordered_start: value.get("ordered_start").and_then(Value::as_u64),
                items: value
                    .get("items")
                    .and_then(Value::as_array)
                    .into_iter()
                    .flatten()
                    .map(indices_array)
                    .collect(),
            },
            "rule" => Self::Rule,
            "emphasis" => Self::Emphasis {
                children: indices(value, "children"),
            },
            "strong" => Self::Strong {
                children: indices(value, "children"),
            },
            "inline_code" => Self::InlineCode(string(value, "code")),
            "link" => Self::Link {
                children: indices(value, "children"),
                href: value
                    .get("href")
                    .and_then(Value::as_str)
                    .map(str::to_string),
            },
            "image" => Self::Image {
                alt: string(value, "alt"),
                title: value
                    .get("title")
                    .and_then(Value::as_str)
                    .map(str::to_string),
                src: value.get("src").and_then(Value::as_str).map(str::to_string),
            },
            "soft_break" => Self::SoftBreak,
            "hard_break" => Self::HardBreak,
            "placeholder" => Self::Placeholder {
                reason: string(value, "reason"),
            },
            _ => Self::Unsupported,
        }
    }

    pub fn inline_label(&self, tree: &ContentTreeWire) -> String {
        match self {
            Self::Text(text) => text.clone(),
            Self::Mention(uri) => format!("@{}", short_id(&uri.primary_id)),
            Self::EventRef(uri) => format!("nostr:{}", short_id(&uri.primary_id)),
            Self::Hashtag(tag) => format!("#{tag}"),
            Self::Url(url) => url.clone(),
            Self::Emoji { shortcode, .. } => format!(":{shortcode}:"),
            Self::Invoice { invoice } => {
                format!("[{} invoice]", invoice.kind.to_ascii_lowercase())
            }
            Self::InlineCode(code) => format!("`{code}`"),
            Self::Paragraph { children }
            | Self::Heading { children, .. }
            | Self::BlockQuote { children } => tree.inline_text(children),
            Self::List {
                ordered_start,
                items,
            } => items
                .iter()
                .enumerate()
                .map(|(idx, item)| {
                    let marker = ordered_start
                        .map(|start| format!("{}.", start + idx as u64))
                        .unwrap_or_else(|| "-".to_string());
                    format!("{marker} {}", tree.inline_text(item))
                })
                .collect::<Vec<_>>()
                .join("\n"),
            Self::CodeBlock { body, .. } => body.clone(),
            Self::Media { urls, kind } => {
                format!("[{} media: {}]", kind.to_ascii_lowercase(), urls.len())
            }
            Self::Emphasis { children } | Self::Strong { children } => tree.inline_text(children),
            Self::Link { children, href } => {
                let label = tree.inline_text(children);
                if label.is_empty() {
                    href.clone().unwrap_or_default()
                } else {
                    label
                }
            }
            Self::SoftBreak => " ".to_string(),
            Self::HardBreak => "\n".to_string(),
            Self::Image { alt, title, .. } => title
                .as_ref()
                .map(|title| format!("[image: {alt} - {title}]"))
                .unwrap_or_else(|| format!("[image: {alt}]")),
            Self::Placeholder { reason } => format!("[{reason}]"),
            _ => String::new(),
        }
    }
}

fn uri(value: &Value) -> Option<WireUri> {
    let uri = value.get("uri")?;
    Some(WireUri {
        uri: string(uri, "uri"),
        kind: string(uri, "kind"),
        primary_id: string(uri, "primary_id"),
        relays: strings(uri, "relays"),
        author: uri
            .get("author")
            .and_then(Value::as_str)
            .map(str::to_string),
        event_kind: uri.get("event_kind").and_then(Value::as_u64),
    })
}

fn invoice(value: &Value) -> Option<WireInvoice> {
    let object = value.get("invoice")?.as_object()?;
    let (kind, payload) = object.iter().next()?;
    Some(WireInvoice {
        kind: kind.clone(),
        value: payload.as_str().unwrap_or_default().to_string(),
    })
}

fn string(value: &Value, key: &str) -> String {
    value
        .get(key)
        .and_then(Value::as_str)
        .unwrap_or_default()
        .to_string()
}

fn strings(value: &Value, key: &str) -> Vec<String> {
    value
        .get(key)
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(Value::as_str)
        .map(str::to_string)
        .collect()
}

fn indices(value: &Value, key: &str) -> Vec<usize> {
    value.get(key).map(indices_array).unwrap_or_default()
}

fn indices_array(value: &Value) -> Vec<usize> {
    value
        .as_array()
        .into_iter()
        .flatten()
        .filter_map(|value| value.as_u64().and_then(|idx| usize::try_from(idx).ok()))
        .collect()
}

fn is_hex_id_64(value: &str) -> bool {
    value.len() == 64 && value.bytes().all(|b| b.is_ascii_hexdigit())
}

fn push_unique(out: &mut Vec<String>, value: &str) {
    if !value.is_empty() && !out.iter().any(|existing| existing == value) {
        out.push(value.to_string());
    }
}

fn short_id(id: &str) -> String {
    let count = id.chars().count();
    if count <= 12 {
        id.to_string()
    } else {
        let head = id.chars().take(6).collect::<String>();
        let tail = id
            .chars()
            .rev()
            .take(6)
            .collect::<Vec<_>>()
            .into_iter()
            .rev()
            .collect::<String>();
        format!("{head}…{tail}")
    }
}

use std::collections::BTreeMap;

use serde_json::Value;

use super::content_tree_wire::{ContentTreeWire, WireUri};

#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct ContentRenderData {
    profiles: BTreeMap<String, ContentProfileRenderData>,
    events: BTreeMap<String, ContentEventRenderData>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ContentProfileRenderData {
    pub pubkey: String,
    pub display_name: Option<String>,
    pub npub: Option<String>,
    pub picture_url: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ContentEventRenderData {
    pub id: String,
    pub author_pubkey: String,
    pub author_display_name: Option<String>,
    pub author_npub: Option<String>,
    pub kind: u64,
    pub created_at: u64,
    pub content_preview: String,
    pub content_tree: Option<ContentTreeWire>,
}

impl ContentRenderData {
    pub fn from_value(value: Option<&Value>) -> Self {
        let Some(value) = value else {
            return Self::default();
        };
        Self {
            profiles: map_values(value.get("profiles"), ContentProfileRenderData::from_value),
            events: map_values(value.get("events"), ContentEventRenderData::from_value),
        }
    }

    pub fn profile_for(&self, uri: &WireUri) -> Option<&ContentProfileRenderData> {
        self.profiles
            .get(&uri.primary_id)
            .or_else(|| self.profiles.get(&uri.uri))
    }

    pub fn event_for(&self, uri: &WireUri) -> Option<&ContentEventRenderData> {
        self.events
            .get(&uri.primary_id)
            .or_else(|| self.events.get(&uri.uri))
    }

    pub fn media_urls(&self) -> Vec<String> {
        let mut out = Vec::new();
        for event in self.events.values() {
            if let Some(tree) = event.content_tree.as_ref() {
                for url in tree.media_urls() {
                    if !out.iter().any(|existing| existing == &url) {
                        out.push(url);
                    }
                }
            }
        }
        out
    }
}

impl ContentProfileRenderData {
    fn from_value(key: &str, value: &Value) -> Option<Self> {
        let display = value.get("display").unwrap_or(value);
        Some(Self {
            pubkey: string(value, "pubkey")
                .or_else(|| string(display, "pubkey"))
                .unwrap_or_else(|| key.to_string()),
            display_name: string(display, "name")
                .or_else(|| string(value, "profile_name"))
                .or_else(|| string(value, "display_name")),
            npub: string(display, "npub").or_else(|| string(value, "npub")),
            picture_url: string(display, "picture_url")
                .or_else(|| string(value, "profile_picture"))
                .or_else(|| string(value, "picture_url")),
        })
    }

    pub fn label(&self) -> &str {
        self.display_name
            .as_deref()
            .or(self.npub.as_deref())
            .unwrap_or(&self.pubkey)
    }
}

impl ContentEventRenderData {
    fn from_value(key: &str, value: &Value) -> Option<Self> {
        let author_display = value.get("author_display").unwrap_or(value);
        Some(Self {
            id: string(value, "id").unwrap_or_else(|| key.to_string()),
            author_pubkey: string(value, "author_pubkey").unwrap_or_default(),
            author_display_name: string(author_display, "name")
                .or_else(|| string(value, "author_display_name")),
            author_npub: string(author_display, "npub").or_else(|| string(value, "author_npub")),
            kind: value.get("kind").and_then(Value::as_u64).unwrap_or(1),
            created_at: value.get("created_at").and_then(Value::as_u64).unwrap_or(0),
            content_preview: string(value, "content_preview").unwrap_or_default(),
            content_tree: value
                .get("content_tree")
                .and_then(ContentTreeWire::from_value),
        })
    }

    pub fn author_label(&self) -> &str {
        self.author_display_name
            .as_deref()
            .or(self.author_npub.as_deref())
            .unwrap_or(&self.author_pubkey)
    }
}

fn map_values<T>(
    value: Option<&Value>,
    parse: impl Fn(&str, &Value) -> Option<T>,
) -> BTreeMap<String, T> {
    let mut out = BTreeMap::new();
    let Some(value) = value else {
        return out;
    };
    if let Some(object) = value.as_object() {
        for (key, value) in object {
            if let Some(parsed) = parse(key, value) {
                out.insert(key.clone(), parsed);
            }
        }
    } else if let Some(array) = value.as_array() {
        for value in array {
            let key = string(value, "pubkey")
                .or_else(|| string(value, "id"))
                .or_else(|| string(value, "uri"))
                .unwrap_or_default();
            if !key.is_empty() {
                if let Some(parsed) = parse(&key, value) {
                    out.insert(key, parsed);
                }
            }
        }
    }
    out
}

fn string(value: &Value, key: &str) -> Option<String> {
    value
        .get(key)
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
}

use ratatui::{
    style::Style,
    text::{Line, Span},
};

pub fn wrap_plain(value: &str, width: usize) -> Vec<Line<'static>> {
    wrap_words(value, width)
        .into_iter()
        .map(Line::from)
        .collect()
}

pub fn wrap_spans(spans: Vec<Span<'static>>, width: usize) -> Vec<Line<'static>> {
    if width == 0 {
        return vec![Line::from("")];
    }

    let mut lines = Vec::new();
    let mut current = Vec::new();
    let mut used = 0usize;

    for span in spans {
        let style = span.style;
        let text = span.content.to_string();
        let mut word = String::new();
        for ch in text.chars() {
            if ch == '\n' {
                push_piece(&mut lines, &mut current, &mut used, &word, style, width);
                word.clear();
                lines.push(line_from_spans(std::mem::take(&mut current)));
                used = 0;
            } else if ch.is_whitespace() {
                push_piece(&mut lines, &mut current, &mut used, &word, style, width);
                word.clear();
                if used > 0 && used < width {
                    current.push(Span::styled(" ".to_string(), style));
                    used += 1;
                }
            } else {
                word.push(ch);
            }
        }
        push_piece(&mut lines, &mut current, &mut used, &word, style, width);
    }

    if !current.is_empty() || lines.is_empty() {
        lines.push(line_from_spans(current));
    }
    lines
}

pub fn wrap_prefixed(
    value: &str,
    width: usize,
    prefix: &str,
    prefix_style: Style,
) -> Vec<Line<'static>> {
    let body_width = width.saturating_sub(prefix.chars().count()).max(1);
    wrap_words(value, body_width)
        .into_iter()
        .map(|line| {
            Line::from(vec![
                Span::styled(prefix.to_string(), prefix_style),
                Span::raw(line),
            ])
        })
        .collect()
}

fn push_piece(
    lines: &mut Vec<Line<'static>>,
    current: &mut Vec<Span<'static>>,
    used: &mut usize,
    piece: &str,
    style: Style,
    width: usize,
) {
    if piece.is_empty() {
        return;
    }
    for chunk in split_chars(piece, width) {
        let len = chunk.chars().count();
        if *used > 0 && *used + len > width {
            lines.push(line_from_spans(std::mem::take(current)));
            *used = 0;
        }
        current.push(Span::styled(chunk, style));
        *used += len;
    }
}

fn split_chars(value: &str, width: usize) -> Vec<String> {
    if value.chars().count() <= width {
        return vec![value.to_string()];
    }
    let mut out = Vec::new();
    let mut chunk = String::new();
    for ch in value.chars() {
        if chunk.chars().count() == width {
            out.push(std::mem::take(&mut chunk));
        }
        chunk.push(ch);
    }
    if !chunk.is_empty() {
        out.push(chunk);
    }
    out
}

fn line_from_spans(spans: Vec<Span<'static>>) -> Line<'static> {
    let out = spans
        .into_iter()
        .filter(|span| span.content != "\n")
        .collect::<Vec<_>>();
    Line::from(out)
}

fn wrap_words(value: &str, width: usize) -> Vec<String> {
    if width == 0 {
        return vec![String::new()];
    }
    let mut out = Vec::new();
    let mut line = String::new();
    for word in value.replace('\n', " ").split_whitespace() {
        let next = if line.is_empty() {
            word.to_string()
        } else {
            format!("{line} {word}")
        };
        if next.chars().count() > width && !line.is_empty() {
            out.push(std::mem::take(&mut line));
            line.push_str(word);
        } else {
            line = next;
        }
    }
    if !line.is_empty() || out.is_empty() {
        out.push(line);
    }
    out
}

