use std::cell::RefCell;
use std::collections::{BTreeMap, HashSet};

use nmp_content::embed_projection::EmbeddedEventEnvelope;
use nmp_content::EventRefResolver;
use ratatui::{
    style::{Color, Modifier, Style},
    text::{Line, Span},
};
use ratatui_image::protocol::Protocol;

mod nostr_content_widget;

use super::{
    content_kind_registry::NostrKindRegistry,
    content_render_data::ContentRenderData,
    content_tree_wire::{ContentTreeWire, WireNode, WireUri},
    nostr_media_grid::NostrMediaGrid,
    nostr_mention_chip::{NostrMentionChip, NostrMentionProfileHost},
    ratatui_text_wrap::{wrap_plain, wrap_prefixed, wrap_spans},
};

pub struct NostrContentView<'a> {
    tree: &'a ContentTreeWire,
    render_data: Option<&'a ContentRenderData>,
    media_images: &'a [(&'a str, &'a Protocol)],
    kind_registry: Option<&'a NostrKindRegistry>,
    embedded_events: Option<&'a BTreeMap<String, EmbeddedEventEnvelope>>,
    event_ref_resolver: Option<&'a dyn EventRefResolver>,
    profile_host: Option<&'a dyn NostrMentionProfileHost>,
    consumer_id: Option<&'a str>,
    // Per-render-pass seen-set. `Widget::render` consumes `self`, so the widget
    // is built fresh by the builder each frame — this set is naturally scoped
    // to a single render pass and dedups multiple references to the same URI
    // within one frame (D8: edge-triggered by render, no polling).
    claimed_this_frame: RefCell<HashSet<String>>,
}

impl<'a> NostrContentView<'a> {
    pub fn new(tree: &'a ContentTreeWire) -> Self {
        Self {
            tree,
            render_data: None,
            media_images: &[],
            kind_registry: None,
            embedded_events: None,
            event_ref_resolver: None,
            profile_host: None,
            consumer_id: None,
            claimed_this_frame: RefCell::new(HashSet::new()),
        }
    }

    pub fn render_data(mut self, render_data: Option<&'a ContentRenderData>) -> Self {
        self.render_data = render_data;
        self
    }

    pub fn media_images(mut self, images: &'a [(&'a str, &'a Protocol)]) -> Self {
        self.media_images = images;
        self
    }

    pub fn kind_registry(mut self, registry: Option<&'a NostrKindRegistry>) -> Self {
        self.kind_registry = registry;
        self
    }

    pub fn embedded_events(
        mut self,
        events: Option<&'a BTreeMap<String, EmbeddedEventEnvelope>>,
    ) -> Self {
        self.embedded_events = events;
        self
    }

    /// Optional host-side sink used to initiate an upstream fetch the first
    /// time a `nostr:` event URI is encountered in a render pass (ADR-0034 /
    /// M16). Defaults to `None`, which preserves preview-only behaviour: no
    /// event refs are resolved and only pre-populated `embedded_events` resolve.
    pub fn event_ref_resolver(mut self, sink: Option<&'a dyn EventRefResolver>) -> Self {
        self.event_ref_resolver = sink;
        self
    }

    /// Optional host-side bridge used to claim and read profile projections for
    /// inline `nostr:npub` mentions. Defaults to `None`, which preserves
    /// preview-only behaviour and renders the reference fallback.
    pub fn profile_host(mut self, host: Option<&'a dyn NostrMentionProfileHost>) -> Self {
        self.profile_host = host;
        self
    }

    /// Optional consumer identifier passed alongside each `resolve_event_ref` call so the
    /// kernel can refcount per-host. Defaults to `None`; if either this or
    /// `event_ref_resolver` is unset, the resolve path is skipped entirely.
    pub fn consumer_id(mut self, id: Option<&'a str>) -> Self {
        self.consumer_id = id;
        self
    }

    pub fn lines(&self, width: usize) -> Vec<Line<'static>> {
        let mut lines = Vec::new();
        let mut root_pos = 0usize;
        while root_pos < self.tree.roots.len() {
            let root = self.tree.roots[root_pos];
            let Some(node) = self.tree.node(root) else {
                root_pos += 1;
                continue;
            };
            if is_inline_root(node) {
                let inline = self.collect_inline_roots(&mut root_pos);
                if !inline.is_empty() {
                    lines.extend(wrap_spans(inline, width));
                }
            } else {
                self.append_node(root, width, &mut lines);
                root_pos += 1;
            }
        }
        if lines.is_empty() {
            lines.push(Line::from(""));
        }
        lines
    }

    fn collect_inline_roots(&self, root_pos: &mut usize) -> Vec<Span<'static>> {
        let mut inline = Vec::new();
        while *root_pos < self.tree.roots.len() {
            let root = self.tree.roots[*root_pos];
            let Some(node) = self.tree.node(root) else {
                *root_pos += 1;
                continue;
            };
            if !is_inline_root(node) {
                break;
            }
            self.append_inline_node(root, &mut inline);
            *root_pos += 1;
        }
        inline
    }

    pub fn preferred_height(&self, width: usize) -> u16 {
        self.tree
            .roots
            .iter()
            .map(|root| self.node_height(*root, width))
            .sum::<u16>()
            .max(1)
    }

    fn append_node(&self, index: usize, width: usize, lines: &mut Vec<Line<'static>>) {
        let Some(node) = self.tree.node(index) else {
            return;
        };
        match node {
            WireNode::Paragraph { children } => {
                self.append_paragraph(children, width, lines);
            }
            WireNode::Heading { level, children } => {
                let prefix = "#".repeat((*level).clamp(1, 6) as usize);
                let mut spans = vec![Span::styled(
                    format!("{prefix} "),
                    Style::default().fg(Color::Rgb(248, 250, 252)),
                )];
                spans.extend(self.inline_spans(children));
                lines.extend(wrap_spans(spans, width));
            }
            WireNode::BlockQuote { children } => {
                lines.extend(self.blockquote_lines(children, width));
            }
            WireNode::EventRef(uri) => {
                lines.extend(self.event_ref_lines(uri, width));
            }
            WireNode::CodeBlock { info, body } => {
                let title = info.as_deref().unwrap_or("code");
                lines.push(Line::from(Span::styled(
                    format!("```{title}"),
                    Style::default().fg(Color::Rgb(148, 163, 184)),
                )));
                lines.extend(body.lines().map(|line| {
                    Line::from(Span::styled(
                        line.to_string(),
                        Style::default().fg(Color::Rgb(253, 186, 116)),
                    ))
                }));
                lines.push(Line::from(Span::styled(
                    "```",
                    Style::default().fg(Color::Rgb(148, 163, 184)),
                )));
            }
            WireNode::List {
                ordered_start,
                items,
            } => {
                for (idx, item) in items.iter().enumerate() {
                    let marker = ordered_start
                        .map(|start| format!("{}.", start + idx as u64))
                        .unwrap_or_else(|| "-".to_string());
                    let body = self.text_for_nodes(item);
                    lines.extend(wrap_prefixed(
                        &body,
                        width,
                        &format!("{marker} "),
                        muted_style(),
                    ));
                }
            }
            WireNode::Rule => lines.push(Line::from("─".repeat(width.min(48)))),
            WireNode::Media { urls, kind } => {
                lines.extend(
                    NostrMediaGrid::new(urls, kind)
                        .images(self.media_images)
                        .lines(width),
                );
            }
            WireNode::Image { alt, src, .. } => {
                let target = src.as_deref().unwrap_or("missing src");
                lines.extend(wrap_prefixed(
                    &format!("{alt} {target}"),
                    width,
                    "[image] ",
                    muted_style(),
                ));
            }
            _ => {
                let mut spans = Vec::new();
                self.append_inline_node(index, &mut spans);
                if spans.is_empty() {
                    let text = node.inline_label(self.tree);
                    if !text.is_empty() {
                        lines.extend(wrap_plain(&text, width));
                    }
                } else {
                    lines.extend(wrap_spans(spans, width));
                }
            }
        }
    }

    fn append_paragraph(&self, children: &[usize], width: usize, lines: &mut Vec<Line<'static>>) {
        let mut inline = Vec::new();
        for child in children {
            let Some(node) = self.tree.node(*child) else {
                continue;
            };
            if let WireNode::EventRef(uri) = node {
                if !inline.is_empty() {
                    lines.extend(wrap_spans(std::mem::take(&mut inline), width));
                }
                lines.extend(self.event_ref_lines(uri, width));
            } else {
                self.append_inline_node(*child, &mut inline);
            }
        }
        if !inline.is_empty() {
            lines.extend(wrap_spans(inline, width));
        }
    }

    fn inline_spans(&self, children: &[usize]) -> Vec<Span<'static>> {
        let mut spans = Vec::new();
        for child in children {
            self.append_inline_node(*child, &mut spans);
        }
        spans
    }

    fn append_inline_node(&self, index: usize, spans: &mut Vec<Span<'static>>) {
        let Some(node) = self.tree.node(index) else {
            return;
        };
        match node {
            WireNode::Text(text) => spans.push(Span::raw(text.clone())),
            WireNode::Mention(uri) => spans.push(
                NostrMentionChip::new(uri)
                    .profile(self.render_data.and_then(|data| data.profile_for(uri)))
                    .profile_host(self.profile_host)
                    .consumer_id(self.consumer_id)
                    .span(),
            ),
            WireNode::EventRef(uri) => {
                let label = self
                    .render_data
                    .and_then(|data| data.event_for(uri))
                    .map(|event| format!("quote {}", event.author_label()))
                    .unwrap_or_else(|| format!("quote {}", short_id(&uri.primary_id)));
                spans.push(Span::styled(
                    label,
                    Style::default().fg(Color::Rgb(196, 181, 253)),
                ));
            }
            WireNode::Hashtag(tag) => spans.push(Span::styled(
                format!("#{tag}"),
                Style::default().fg(Color::Rgb(45, 212, 191)),
            )),
            WireNode::Url(url) => spans.push(Span::styled(
                url.clone(),
                Style::default().fg(Color::Rgb(96, 165, 250)),
            )),
            WireNode::Emoji { shortcode, .. } => spans.push(Span::raw(format!(":{shortcode}:"))),
            WireNode::Invoice { invoice } => spans.push(Span::styled(
                format!("[{} invoice]", invoice.kind.to_ascii_lowercase()),
                Style::default().fg(Color::Rgb(250, 204, 21)),
            )),
            WireNode::InlineCode(code) => spans.push(Span::styled(
                format!("`{code}`"),
                Style::default().fg(Color::Rgb(253, 186, 116)),
            )),
            WireNode::Emphasis { children } => {
                let start = spans.len();
                for child in children {
                    self.append_inline_node(*child, spans);
                }
                for span in &mut spans[start..] {
                    span.style = span.style.add_modifier(Modifier::ITALIC);
                }
            }
            WireNode::Strong { children } => {
                let start = spans.len();
                for child in children {
                    self.append_inline_node(*child, spans);
                }
                for span in &mut spans[start..] {
                    span.style = span.style.add_modifier(Modifier::BOLD);
                }
            }
            WireNode::Link { children, href } => {
                let start = spans.len();
                if children.is_empty() {
                    spans.push(Span::styled(
                        href.clone().unwrap_or_default(),
                        Style::default().fg(Color::Rgb(96, 165, 250)),
                    ));
                } else {
                    for child in children {
                        self.append_inline_node(*child, spans);
                    }
                    for span in &mut spans[start..] {
                        span.style = span.style.fg(Color::Rgb(96, 165, 250));
                    }
                }
            }
            WireNode::Image { alt, src, .. } => {
                let target = src.as_deref().unwrap_or("missing src");
                spans.push(Span::styled(
                    format!("[image: {alt} {target}]"),
                    Style::default().fg(Color::Rgb(186, 230, 253)),
                ));
            }
            WireNode::Media { urls, kind } => spans.push(Span::styled(
                format!("[{} media: {}]", kind.to_ascii_lowercase(), urls.len()),
                Style::default().fg(Color::Rgb(186, 230, 253)),
            )),
            WireNode::SoftBreak => spans.push(Span::raw(" ")),
            WireNode::HardBreak => spans.push(Span::raw("\n")),
            WireNode::Paragraph { children }
            | WireNode::Heading { children, .. }
            | WireNode::BlockQuote { children } => {
                for child in children {
                    self.append_inline_node(*child, spans);
                }
            }
            _ => {
                let text = node.inline_label(self.tree);
                if !text.is_empty() {
                    spans.push(Span::raw(text));
                }
            }
        }
    }

    fn text_for_nodes(&self, children: &[usize]) -> String {
        children
            .iter()
            .filter_map(|idx| self.tree.node(*idx))
            .map(|node| node.inline_label(self.tree))
            .filter(|text| !text.is_empty())
            .collect::<Vec<_>>()
            .join("\n")
    }

    /// Inline fallback lines for a markdown blockquote (`> …`). Used by the
    /// preview/`lines()` path; the interactive widget path renders blockquotes
    /// with the same `> ` prefix in `nostr_content_widget.rs`.
    fn blockquote_lines(&self, children: &[usize], width: usize) -> Vec<Line<'static>> {
        self.text_for_nodes(children)
            .split('\n')
            .flat_map(|line| wrap_prefixed(line, width, "> ", muted_style()))
            .collect()
    }

    /// Inline fallback lines for an unresolved `nostr:` event reference. The
    /// interactive widget path renders the resolved event via the kind-registry
    /// `EmbeddedEvent`; this preview/`lines()` path has no host, so it surfaces
    /// the same one-line `quote <id>` affordance the legacy quote card used.
    fn event_ref_lines(&self, uri: &WireUri, width: usize) -> Vec<Line<'static>> {
        let label = self
            .render_data
            .and_then(|data| data.event_for(uri))
            .map(|event| format!("quote {} · kind:{}", event.author_label(), event.kind))
            .unwrap_or_else(|| format!("quote {}", short_id(&uri.primary_id)));
        wrap_prefixed(&label, width, "", muted_style())
    }

    fn node_height(&self, index: usize, width: usize) -> u16 {
        let Some(node) = self.tree.node(index) else {
            return 0;
        };
        match node {
            WireNode::Paragraph { children } => self.paragraph_height(children, width),
            WireNode::Media { urls, kind } => NostrMediaGrid::new(urls, kind)
                .images(self.media_images)
                .preferred_height()
                .saturating_add(1),
            WireNode::Image { src: Some(src), .. } => {
                NostrMediaGrid::new(std::slice::from_ref(src), "image")
                    .images(self.media_images)
                    .preferred_height()
                    .saturating_add(1)
            }
            WireNode::EventRef(uri) => self.event_ref_lines(uri, width).len().max(1) as u16,
            WireNode::BlockQuote { children } => {
                self.blockquote_lines(children, width).len().max(1) as u16
            }
            _ => {
                let mut lines = Vec::new();
                self.append_node(index, width, &mut lines);
                lines.len().max(1) as u16
            }
        }
    }

    fn paragraph_height(&self, children: &[usize], width: usize) -> u16 {
        let mut inline = Vec::new();
        let mut height = 0u16;
        for child in children {
            match self.tree.node(*child) {
                Some(WireNode::EventRef(_) | WireNode::Media { .. } | WireNode::Image { .. }) => {
                    height = height.saturating_add(nonempty_wrapped_height(
                        std::mem::take(&mut inline),
                        width,
                    ));
                    height = height.saturating_add(self.node_height(*child, width));
                }
                Some(_) => self.append_inline_node(*child, &mut inline),
                None => {}
            }
        }
        height.saturating_add(nonempty_wrapped_height(inline, width))
    }
}

fn nonempty_wrapped_height(spans: Vec<Span<'static>>, width: usize) -> u16 {
    wrap_spans(spans, width)
        .into_iter()
        .filter(|line| line.spans.iter().any(|span| !span.content.is_empty()))
        .count() as u16
}

#[rustfmt::skip]
fn is_inline_root(node: &WireNode) -> bool {
    use WireNode::*;
    !matches!(node, Paragraph { .. } | Heading { .. } | BlockQuote { .. } | CodeBlock { .. } | List { .. } | Rule | Media { .. } | Image { .. } | EventRef(_))
}

fn short_id(id: &str) -> String {
    if id.len() > 12 {
        return format!("{}…{}", &id[..6], &id[id.len() - 6..]);
    }
    id.to_string()
}

fn muted_style() -> Style {
    Style::default().fg(Color::Rgb(148, 163, 184))
}

use ratatui::{
    buffer::Buffer,
    layout::Rect,
    text::Line,
    widgets::{Paragraph, Widget, Wrap},
};

use super::super::{
    content_kind_registry::EmbeddedEvent,
    content_tree_wire::{WireNode, WireUri},
    nostr_media_grid::NostrMediaGrid,
    ratatui_text_wrap::wrap_spans,
};
use super::{is_inline_root, NostrContentView};

impl Widget for NostrContentView<'_> {
    fn render(self, area: Rect, buf: &mut Buffer) {
        let mut cursor = area.y;
        let mut root_pos = 0usize;
        while root_pos < self.tree.roots.len() {
            let root = self.tree.roots[root_pos];
            let Some(node) = self.tree.node(root) else {
                root_pos += 1;
                continue;
            };
            if is_inline_root(node) {
                let inline = self.collect_inline_roots(&mut root_pos);
                self.render_lines(
                    wrap_spans(inline, area.width as usize),
                    area,
                    buf,
                    &mut cursor,
                );
            } else {
                self.render_node(root, area, buf, &mut cursor);
                root_pos += 1;
            }
            if cursor >= area.bottom() {
                break;
            }
        }
        if cursor == area.y {
            Paragraph::new("").render(area, buf);
        }
    }
}

impl NostrContentView<'_> {
    fn render_node(&self, index: usize, area: Rect, buf: &mut Buffer, cursor: &mut u16) {
        let Some(node) = self.tree.node(index) else {
            return;
        };
        match node {
            WireNode::Paragraph { children } => self.render_paragraph(children, area, buf, cursor),
            WireNode::Media { urls, kind } => self.render_media(urls, kind, area, buf, cursor),
            WireNode::Image { src, .. } => {
                if let Some(src) = src {
                    self.render_media(std::slice::from_ref(src), "image", area, buf, cursor);
                }
            }
            WireNode::EventRef(uri) => {
                if !self.render_embedded_event(uri, area, buf, cursor) {
                    self.render_unresolved_embed(uri, area, buf, cursor);
                }
            }
            WireNode::BlockQuote { children } => {
                self.render_blockquote(children, area, buf, cursor);
            }
            _ => {
                let lines = {
                    let mut out = Vec::new();
                    self.append_node(index, area.width as usize, &mut out);
                    out
                };
                self.render_lines(lines, area, buf, cursor);
            }
        }
    }

    fn render_paragraph(&self, children: &[usize], area: Rect, buf: &mut Buffer, cursor: &mut u16) {
        let mut inline = Vec::new();
        for child in children {
            let Some(node) = self.tree.node(*child) else {
                continue;
            };
            match node {
                WireNode::EventRef(uri) => {
                    self.render_lines(
                        wrap_spans(std::mem::take(&mut inline), area.width as usize),
                        area,
                        buf,
                        cursor,
                    );
                    if !self.render_embedded_event(uri, area, buf, cursor) {
                        self.render_node(*child, area, buf, cursor);
                    }
                }
                WireNode::Media { .. } | WireNode::Image { .. } => {
                    self.render_lines(
                        wrap_spans(std::mem::take(&mut inline), area.width as usize),
                        area,
                        buf,
                        cursor,
                    );
                    self.render_node(*child, area, buf, cursor);
                }
                _ => self.append_inline_node(*child, &mut inline),
            }
        }
        self.render_lines(wrap_spans(inline, area.width as usize), area, buf, cursor);
    }

    fn render_embedded_event(
        &self,
        uri: &WireUri,
        area: Rect,
        buf: &mut Buffer,
        cursor: &mut u16,
    ) -> bool {
        let Some(registry) = self.kind_registry else {
            return false;
        };
        // Edge-triggered fetch: when both resolver and consumer are configured,
        // ask the host to resolve this URI before we look up the envelope. The
        // request is independent of cache state — warm cache resolves refcount
        // upstream as a near no-op; cold cache resolves trigger the OneshotApi
        // path and the envelope surfaces in a later snapshot. Dedup per render
        // pass via the seen-set so multiple references to the same URI in one
        // frame collapse into a single host call.
        if let (Some(sink), Some(consumer)) = (self.event_ref_resolver, self.consumer_id) {
            let mut seen = self.claimed_this_frame.borrow_mut();
            if seen.insert(uri.uri.clone()) {
                sink.resolve_event_ref(&uri.uri, consumer);
            }
        }
        let Some(envelope) = self.envelope_for(uri) else {
            return false;
        };
        // Component-owned kind:0 (iOS #833): thread the content view's own
        // presentation-owned profile host into the embed so the byline
        // renderer claims the author's profile and reads the live-resolved
        // name, instead of the static `author_display_name` projection field.
        let widget =
            EmbeddedEvent::new(envelope, registry).author_host(self.profile_host, self.consumer_id);
        let height = widget.preferred_height(area.width);
        let rect = take_area(area, cursor, height);
        if rect.is_empty() {
            return true;
        }
        widget.render(rect, buf);
        *cursor = rect.bottom().saturating_add(1).min(area.bottom());
        true
    }

    fn envelope_for(
        &self,
        uri: &WireUri,
    ) -> Option<&nmp_content::embed_projection::EmbeddedEventEnvelope> {
        let events = self.embedded_events?;
        events.get(&uri.primary_id).or_else(|| events.get(&uri.uri))
    }

    /// Render an unresolved `nostr:` event reference — the kernel has not
    /// shipped its envelope yet (no host wired, or the fetch is in flight). The
    /// resolved render dispatches through the kind-registry `EmbeddedEvent`; this
    /// is the inline placeholder line shown until then.
    fn render_unresolved_embed(
        &self,
        uri: &WireUri,
        area: Rect,
        buf: &mut Buffer,
        cursor: &mut u16,
    ) {
        let lines = self.event_ref_lines(uri, area.width as usize);
        self.render_lines(lines, area, buf, cursor);
    }

    /// Render a markdown blockquote (`> …`). Mirrors the `lines()` path's
    /// `blockquote_lines`; not an embedded-event quote card.
    fn render_blockquote(
        &self,
        children: &[usize],
        area: Rect,
        buf: &mut Buffer,
        cursor: &mut u16,
    ) {
        let lines = self.blockquote_lines(children, area.width as usize);
        self.render_lines(lines, area, buf, cursor);
    }

    fn render_media(
        &self,
        urls: &[String],
        kind: &str,
        area: Rect,
        buf: &mut Buffer,
        cursor: &mut u16,
    ) {
        let grid = NostrMediaGrid::new(urls, kind).images(self.media_images);
        let rect = take_area(area, cursor, grid.preferred_height());
        if rect.is_empty() {
            return;
        }
        grid.render(rect, buf);
        *cursor = rect.bottom().saturating_add(1).min(area.bottom());
    }

    fn render_lines(
        &self,
        lines: Vec<Line<'static>>,
        area: Rect,
        buf: &mut Buffer,
        cursor: &mut u16,
    ) {
        let lines = lines
            .into_iter()
            .filter(|line| line.spans.iter().any(|span| !span.content.is_empty()))
            .collect::<Vec<_>>();
        if lines.is_empty() {
            return;
        }
        let rect = take_area(area, cursor, lines.len() as u16);
        if rect.is_empty() {
            return;
        }
        Paragraph::new(lines)
            .wrap(Wrap { trim: false })
            .render(rect, buf);
        *cursor = rect.bottom();
    }
}

fn take_area(area: Rect, cursor: &mut u16, wanted_height: u16) -> Rect {
    if *cursor >= area.bottom() || wanted_height == 0 {
        return Rect::new(area.x, area.bottom(), area.width, 0);
    }
    let available = area.bottom().saturating_sub(*cursor);
    Rect {
        x: area.x,
        y: *cursor,
        width: area.width,
        height: wanted_height.min(available),
    }
}

/// Wire type for a Nostr user profile, decoded from the Rust-owned profile
/// projection before it reaches the Ratatui view layer.
///
/// `npub` and `npub_short` are already Rust-formatted. TUI code should render
/// them as provided rather than reformatting keys locally.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ProfileWire {
    pub pubkey: String,
    pub display_name: Option<String>,
    pub about: Option<String>,
    pub picture_url: Option<String>,
    pub nip05: Option<String>,
    pub npub: String,
    pub npub_short: String,
}

impl ProfileWire {
    pub fn display(&self) -> &str {
        non_empty(self.display_name.as_deref()).unwrap_or(self.npub_short.as_str())
    }

    pub fn nip05(&self) -> Option<&str> {
        non_empty(self.nip05.as_deref())
    }

    pub fn picture_url(&self) -> Option<&str> {
        non_empty(self.picture_url.as_deref())
    }

    pub fn initials(&self) -> String {
        let label = self.display();
        let mut letters = label
            .split_whitespace()
            .filter_map(|part| part.chars().next())
            .filter(|ch| ch.is_alphanumeric())
            .take(2)
            .collect::<String>();
        if letters.is_empty() {
            letters = self.npub_short.chars().take(2).collect();
        }
        letters.to_uppercase()
    }
}

fn non_empty(value: Option<&str>) -> Option<&str> {
    value.map(str::trim).filter(|value| !value.is_empty())
}

use ratatui::{
    buffer::Buffer,
    layout::{Alignment, Rect},
    style::{Color, Modifier, Style},
    text::{Line, Span},
    widgets::{Block, Borders, Paragraph, Widget},
};
use ratatui_image::{Image, protocol::Protocol};

use super::profile_wire::ProfileWire;

/// Host bridge for profile projections owned by the NMP kernel.
///
/// Immediate-mode TUI widgets call this while rendering visible profile
/// references. The host supplies the platform adapter; the widget owns the
/// resolve intent and reads the current projection each frame.
///
/// ADR-0063 (#1671): `resolve_ref` replaces the old `claim_profile` — the
/// host calls a typed profile-ref adapter and reads the resolved row from the shell's
/// `RefProfileStore` mirror, not from the old `claimed_profiles` map.
pub trait NostrProfileHost {
    fn profile_for_pubkey(&self, pubkey: &str) -> ProfileWire;
    /// Issue a typed profile-ref resolve to the kernel. Called by the widget on every render frame for
    /// each visible pubkey; the kernel deduplicates and refcounts.
    fn resolve_ref(&self, pubkey: &str, consumer_id: &str);
    fn release_ref(&self, pubkey: &str, consumer_id: &str);
}

const PALETTE: [Color; 8] = [
    Color::Rgb(244, 114, 182),
    Color::Rgb(56, 189, 248),
    Color::Rgb(52, 211, 153),
    Color::Rgb(251, 191, 36),
    Color::Rgb(167, 139, 250),
    Color::Rgb(248, 113, 113),
    Color::Rgb(45, 212, 191),
    Color::Rgb(250, 204, 21),
];

/// Circular-ish terminal avatar with deterministic identicon fallback.
///
/// Terminals render cells, not real circles, so this widget uses a compact
/// bordered tile with profile initials and a stable pubkey-derived accent.
pub struct NostrAvatar<'a> {
    profile: AvatarProfile<'a>,
    image: Option<&'a Protocol>,
    border_style: Style,
}

enum AvatarProfile<'a> {
    Borrowed(&'a ProfileWire),
    Owned(ProfileWire),
}

impl<'a> NostrAvatar<'a> {
    pub fn new(profile: &'a ProfileWire) -> Self {
        Self {
            profile: AvatarProfile::Borrowed(profile),
            image: None,
            border_style: Style::default().fg(accent_for(&profile.pubkey)),
        }
    }

    pub fn for_pubkey(pubkey: &str, host: &dyn NostrProfileHost) -> Self {
        const CONSUMER_ID: &str = "tui/user-avatar";
        host.resolve_ref(pubkey, CONSUMER_ID);
        let profile = host.profile_for_pubkey(pubkey);
        let border_style = Style::default().fg(accent_for(&profile.pubkey));
        Self {
            profile: AvatarProfile::Owned(profile),
            image: None,
            border_style,
        }
    }

    pub fn image(mut self, image: Option<&'a Protocol>) -> Self {
        self.image = image;
        self
    }

    pub fn border_style(mut self, style: Style) -> Self {
        self.border_style = style;
        self
    }

    fn profile(&self) -> &ProfileWire {
        match &self.profile {
            AvatarProfile::Borrowed(profile) => profile,
            AvatarProfile::Owned(profile) => profile,
        }
    }
}

impl Widget for NostrAvatar<'_> {
    fn render(self, area: Rect, buf: &mut Buffer) {
        let profile = self.profile();
        let accent = accent_for(&profile.pubkey);
        let initials = profile.initials();
        let block = Block::default()
            .borders(Borders::ALL)
            .border_style(self.border_style)
            .style(Style::default().bg(Color::Reset));
        let inner = block.inner(area);
        block.render(area, buf);

        if inner.is_empty() {
            return;
        }
        if let Some(image) = self.image {
            Image::new(image).allow_clipping(true).render(inner, buf);
            return;
        }

        let fill = Style::default()
            .fg(Color::Black)
            .bg(accent)
            .add_modifier(Modifier::BOLD);
        let line = Line::from(Span::styled(initials, fill));
        Paragraph::new(line)
            .alignment(Alignment::Center)
            .style(fill)
            .render(center_line(inner), buf);
    }
}

fn accent_for(pubkey: &str) -> Color {
    let hash = pubkey.bytes().fold(5381usize, |acc, byte| {
        ((acc << 5).wrapping_add(acc)) ^ byte as usize
    });
    PALETTE[hash % PALETTE.len()]
}

fn center_line(area: Rect) -> Rect {
    Rect {
        x: area.x,
        y: area.y + area.height.saturating_sub(1) / 2,
        width: area.width,
        height: 1,
    }
}

