    style: Style,
}

impl<'a> NostrProfileName<'a> {
    pub fn new(profile: &'a ProfileWire) -> Self {
        Self {
            profile,
            style: Style::default()
                .fg(Color::White)
                .add_modifier(Modifier::BOLD),
        }
    }

    pub fn style(mut self, style: Style) -> Self {
        self.style = style;
        self
    }

