/// Compact author header: avatar, display name, and optional NIP-05 badge.
pub struct NostrUserCard<'a> {
    profile: &'a ProfileWire,
    avatar_image: Option<&'a Protocol>,
    style: Style,
}

impl<'a> NostrUserCard<'a> {
    pub fn new(profile: &'a ProfileWire) -> Self {
        Self {
            profile,
            avatar_image: None,
            style: Style::default().fg(Color::White).bg(Color::Rgb(12, 16, 28)),
        }
    }

    pub fn avatar_image(mut self, image: Option<&'a Protocol>) -> Self {
        self.avatar_image = image;
        self
    }

    pub fn style(mut self, style: Style) -> Self {
        self.style = style;
        self
    }
}

impl Widget for NostrUserCard<'_> {
    fn render(self, area: Rect, buf: &mut Buffer) {
        let block = Block::default()
            .borders(Borders::ALL)
            .border_style(Style::default().fg(Color::Rgb(30, 41, 59)))
            .style(self.style);
        let inner = block.inner(area);
        block.render(area, buf);
        if inner.is_empty() {
            return;
        }

        let chunks = Layout::horizontal([Constraint::Length(14), Constraint::Min(0)]).split(inner);
        NostrAvatar::new(self.profile)
            .image(self.avatar_image)
            .render(chunks[0], buf);

        let text_area = inset(chunks[1], 1, 0);
        let name = NostrProfileName::new(self.profile).line();
        let badge = NostrNip05Badge::from_profile(self.profile)
            .map(|badge| badge.line())
            .unwrap_or_else(|| Line::from(""));

        Paragraph::new(vec![name, badge])
            .style(self.style)
            .render(text_area, buf);
    }
}

fn inset(area: Rect, x: u16, y: u16) -> Rect {
    Rect {
        x: area.x.saturating_add(x),
        y: area.y.saturating_add(y),
        width: area.width.saturating_sub(x),
        height: area.height.saturating_sub(y),
    }
}

/// Wire type for a Nostr user profile, decoded from the Rust-owned profile
/// projection before it reaches the Ratatui view layer.
///
/// `npub` and `npub_short` are already Rust-formatted. TUI code should render
/// them as provided rather than reformatting keys locally.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ProfileWire {
    pub pubkey: String,
    pub display_name: Option<String>,
    pub about: Option<String>,
    pub picture_url: Option<String>,
    pub nip05: Option<String>,
    pub npub: String,
    pub npub_short: String,
}

impl ProfileWire {
    pub fn display(&self) -> &str {
        non_empty(self.display_name.as_deref()).unwrap_or(self.npub_short.as_str())
    }

    pub fn nip05(&self) -> Option<&str> {
        non_empty(self.nip05.as_deref())
    }

    pub fn picture_url(&self) -> Option<&str> {
        non_empty(self.picture_url.as_deref())
    }

    pub fn initials(&self) -> String {
        let label = self.display();
        let mut letters = label
            .split_whitespace()
            .filter_map(|part| part.chars().next())
            .filter(|ch| ch.is_alphanumeric())
            .take(2)
            .collect::<String>();
        if letters.is_empty() {
            letters = self.npub_short.chars().take(2).collect();
        }
        letters.to_uppercase()
    }
}

fn non_empty(value: Option<&str>) -> Option<&str> {
    value.map(str::trim).filter(|value| !value.is_empty())
}

use iced::widget::container;
use iced::widget::image::Handle;
use iced::ContentFit;
use iced::{Border, Color, Element, Length};

/// Circular avatar widget with deterministic pubkey-derived tint.
///
/// When `picture_bytes` are supplied the image is rendered as a circle (via
/// container clip + border-radius). Otherwise renders a tinted circle with
/// initials, identical to the TUI surface.
pub struct UserAvatar {
    pubkey_hex: String,
    display_name: Option<String>,
    picture_handle: Option<Handle>,
    size: f32,
}

impl UserAvatar {
    #[must_use]
    pub fn new(pubkey_hex: &str) -> Self {
        Self {
            pubkey_hex: pubkey_hex.to_string(),
            display_name: None,
            picture_handle: None,
            size: 36.0,
        }
    }

    #[must_use]
    pub fn display_name(mut self, name: Option<&str>) -> Self {
        self.display_name = name.map(String::from);
        self
    }

    /// Supply a pre-built image Handle (created once in update(), never in
    /// view()). When present, renders the actual profile picture clipped to a
    /// circle. Passing a Handle with a stable ID prevents per-frame GPU
    /// re-uploads and the flickering that would cause.
    #[must_use]
    pub fn picture_handle(mut self, handle: Handle) -> Self {
        self.picture_handle = Some(handle);
        self
    }

    #[must_use]
    pub fn size(mut self, size: f32) -> Self {
        self.size = size;
        self
    }

    pub fn into_element<Message: 'static>(self) -> Element<'static, Message> {
        let size = self.size;

        if let Some(handle) = self.picture_handle {
            // Render actual profile picture clipped to a circle.
            container(
                iced::widget::image(handle)
                    .width(Length::Fixed(size))
                    .height(Length::Fixed(size))
                    .content_fit(ContentFit::Cover),
            )
            .width(Length::Fixed(size))
            .height(Length::Fixed(size))
            .clip(true)
            .style(move |_| container::Style {
                border: Border {
                    radius: (size / 2.0).into(),
                    color: Color::TRANSPARENT,
                    width: 0.0,
                },
                ..Default::default()
            })
            .into()
        } else {
            // Deterministic tinted circle with initials.
            let color = hex_color(&nmp_core::display::avatar_color_hex(&self.pubkey_hex));
            let initials = if let Some(ref name) = self.display_name {
                nmp_core::display::display_name_initials(name)
            } else {
                let npub = nmp_core::display::to_npub(&self.pubkey_hex);
                nmp_core::display::avatar_initials(&npub)
            };

            container(
                iced::widget::text(initials)
                    .size(size * 0.4)
                    .align_x(iced::alignment::Horizontal::Center)
                    .align_y(iced::alignment::Vertical::Center),
            )
            .width(Length::Fixed(size))
            .height(Length::Fixed(size))
            .align_x(iced::alignment::Horizontal::Center)
            .align_y(iced::alignment::Vertical::Center)
            .style(move |_| container::Style {
                background: Some(iced::Background::Color(color)),
                border: Border {
                    radius: (size / 2.0).into(),
                    ..Default::default()
                },
                ..Default::default()
            })
            .into()
        }
    }
}

fn hex_color(hex: &str) -> iced::Color {
    let h = hex.trim_start_matches('#');
    if h.len() == 6 {
        if let (Ok(r), Ok(g), Ok(b)) = (
            u8::from_str_radix(&h[0..2], 16),
            u8::from_str_radix(&h[2..4], 16),
            u8::from_str_radix(&h[4..6], 16),
        ) {
            return iced::Color::from_rgb8(r, g, b);
        }
    }
    iced::Color::from_rgb8(120, 120, 120)
}

