impl<'a> ProfileCard<'a> {
    #[must_use]
    pub fn new(profile: &'a ProfileProjection) -> Self {
        Self { profile }
    }

    pub fn into_element<Message: 'static>(self) -> Element<'a, Message> {
        let profile = self.profile;
        let label = profile
            .display_name
            .as_deref()
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(str::to_string)
            .unwrap_or_else(|| short_npub(&profile.pubkey));

        let mut body = column![
            row![
                text(label)
                    .size(15)
                    .font(iced::Font {
                        weight: iced::font::Weight::Bold,
                        ..iced::Font::default()
                    })
                    .style(|_| iced::widget::text::Style {
                        color: Some(Color::from_rgb8(241, 245, 249)),
                    }),
                text("kind:0")
                    .size(10)
                    .style(|_| iced::widget::text::Style { color: Some(MUTED) }),
            ]
            .spacing(8)
            .align_y(Alignment::Center),
            text(short_npub(&profile.pubkey))
                .size(11)
                .style(|_| iced::widget::text::Style { color: Some(MUTED) }),
        ]
        .spacing(6);

        if let Some(nip05) = profile
            .nip05
            .as_deref()
            .map(str::trim)
            .filter(|s| !s.is_empty())
        {
            body = body.push(
                text(nip05.strip_prefix("_@").unwrap_or(nip05))
                    .size(12)
                    .style(|_| iced::widget::text::Style {
                        color: Some(Color::from_rgb8(110, 231, 183)),
                    }),
            );
        }

        if let Some(about) = profile
            .about
            .as_deref()
            .map(str::trim)
            .filter(|s| !s.is_empty())
        {
            body = body.push(
                text(about)
                    .size(12)
                    .style(|_| iced::widget::text::Style { color: Some(MUTED) }),
            );
        }

        container(body)
            .width(Length::Fill)
            .padding(12)
            .style(|_| container::Style {
                background: Some(iced::Background::Color(FAINT_BG)),
                border: Border {
                    color: BORDER_COLOR,
                    width: 1.0,
                    radius: 6.0.into(),
                },
                ..Default::default()
            })
            .into()
    }
}

import { Show, createSignal, onMount } from "solid-js";

// Identity record for a detected web signer. On the web the canonical signer is
// a NIP-07 browser extension (Alby, nos2x, …) exposed as `window.nostr`. The
// extension is generic — the page cannot enumerate which one — so detection
// yields a single `nip07` entry when `window.nostr` is present.
export interface NostrSignerInfo {
  kind: "nip07";
  /** Human-readable label shown on the card. */
  displayName: string;
}

// Minimal NIP-07 provider shape the block touches. The host's sign-in flow
// owns the rest (getPublicKey → setSigner).
interface Nip07Provider {
  getPublicKey(): Promise<string>;
}

function detectNip07(): Nip07Provider | undefined {
  if (typeof window === "undefined") return undefined;
  const w = window as unknown as { nostr?: Nip07Provider };
  return w.nostr && typeof w.nostr.getPublicKey === "function" ? w.nostr : undefined;
}

// Login block — detects a NIP-07 browser-signer and surfaces it as a one-click
// sign-in card, falling back to a manual key-entry row (and an install hint)
// when none is present. Mirrors the SwiftUI / Compose `NostrLoginBlock` signer
// detection + manual fallback. Detection runs lazily in `onMount` (never at
// module load) so `window.nostr` is fully injected by the time it runs.
//
// The host wires `onSignerSelected` to its sign-in flow (call
// `window.nostr.getPublicKey()` then install the signer) and `onManualKey` to
// its key-import flow.
export function NostrLoginBlock(props: {
  onSignerSelected?: (info: NostrSignerInfo, provider: Nip07Provider) => void;
  onManualKey?: (key: string) => void;
}) {
  const [provider, setProvider] = createSignal<Nip07Provider | undefined>(undefined);
  const [key, setKey] = createSignal("");

  // Lazy detection — NIP-07 extensions inject `window.nostr` asynchronously, so
  // probe on mount (and once more on the next tick) rather than at import time.
  onMount(() => {
    setProvider(detectNip07());
    if (!detectNip07()) {
      const t = setTimeout(() => setProvider(detectNip07()), 300);
      return () => clearTimeout(t);
    }
  });

  return (
    <div class="nostr-login-block" data-has-nip07={provider() ? "true" : "false"}>
      <Show
        when={provider()}
        fallback={
          <div class="nostr-login-block__hint">
            No NIP-07 browser signer detected. Install a signer extension (e.g. Alby or
            nos2x), or paste a key below.
          </div>
        }
      >
        {(p) => (
          <button
            type="button"
            class="nostr-login-block__signer"
            onClick={() =>
              props.onSignerSelected?.({ kind: "nip07", displayName: "Browser extension (NIP-07)" }, p())
            }
          >
            <span class="nostr-login-block__signer-icon" aria-hidden="true">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor">
                <path d="M12 1l3 6 6 .9-4.5 4.3 1 6.3L12 16.5 6.5 18.5l1-6.3L3 7.9 9 7z" />
              </svg>
            </span>
            <span class="nostr-login-block__signer-label">Sign in with browser extension (NIP-07)</span>
          </button>
        )}
      </Show>

      <form
        class="nostr-login-block__manual"
        onSubmit={(e) => {
          e.preventDefault();
          const v = key().trim();
          if (v.length > 0) props.onManualKey?.(v);
        }}
      >
        <input
          class="nostr-login-block__input"
          type="text"
          inputmode="text"
          autocomplete="off"
          spellcheck={false}
          placeholder="npub1… (read-only) or nsec1…"
          value={key()}
          onInput={(e) => setKey(e.currentTarget.value)}
          aria-label="Nostr key"
        />
        <button type="submit" class="nostr-login-block__submit" disabled={key().trim().length === 0}>
          Use key
        </button>
      </form>
    </div>
  );
}

import { For, Show } from "solid-js";

// One relay row, folded from the kernel snapshot: `url` + canonical `role`
// string from `configured_relays`, and `connection` from the top-level
// `relay_statuses` field. `connection` is one of the closed token set
// `connected | connecting | disconnected | error` (case-insensitive). All raw
// protocol data — the component owns only presentation (dot color, role label).
export interface RelayRow {
  url: string;
  role: string;
  connection: string;
}

// Relay list — shows configured relays with a live connection-status dot and
// role badges. Mirrors the SwiftUI / NDK `NostrRelayList`: data comes straight
// from the NMP snapshot; the host folds `relay_statuses` into each row's
// `connection`. Render-only — the host owns fetching and relay config.
export function NostrRelayList(props: {
  relays: RelayRow[];
  onRelayTap?: (relay: RelayRow) => void;
}) {
  return (
    <Show
      when={props.relays.length > 0}
      fallback={<div class="nostr-relay-list__empty">No relays configured</div>}
    >
      <ul class="nostr-relay-list" role="list">
        <For each={props.relays}>
          {(relay) => (
            <li class="nostr-relay-row">
              <button
                type="button"
                class="nostr-relay-row__btn"
                onClick={() => props.onRelayTap?.(relay)}
                disabled={!props.onRelayTap}
              >
                <span
                  class="nostr-relay-row__dot"
                  data-state={connectionState(relay.connection)}
                  style={{ "background-color": connectionColor(relay.connection) }}
                  title={relay.connection}
                  aria-label={`connection: ${relay.connection}`}
                />
                <span class="nostr-relay-row__url">{displayUrl(relay.url)}</span>
                <span class="nostr-relay-row__roles">
                  <For each={roleTokens(relay.role)}>
                    {(token) => (
                      <span
                        class="nostr-relay-row__badge"
                        style={{ color: roleTint(token), "border-color": roleTint(token) }}
                      >
                        {roleLabel(token)}
                      </span>
                    )}
                  </For>
                </span>
              </button>
            </li>
          )}
        </For>
      </ul>
    </Show>
  );
}

/** Strip the `wss://` / `ws://` scheme and any trailing slash for display. */
export function displayUrl(url: string): string {
  return url.replace(/^wss?:\/\//, "").replace(/\/$/, "");
}

function connectionState(connection: string): string {
  return connection.toLowerCase();
}

// Closed token set → semantic color. Edit to match your theme.
function connectionColor(connection: string): string {
  switch (connection.toLowerCase()) {
    case "connected":
      return "rgb(46, 194, 126)";
    case "connecting":
      return "rgb(229, 165, 10)";
    case "error":
      return "rgb(224, 79, 79)";
    default:
      return "rgb(120, 120, 132)";
  }
}

/** A canonical role string is comma-separated, e.g. `both,indexer`. */
function roleTokens(role: string): string[] {
  return role
    .split(",")
    .map((t) => t.trim())
    .filter((t) => t.length > 0);
}

function roleLabel(token: string): string {
  switch (token) {
    case "both":
      return "read+write";
    case "read":
      return "read";
    case "write":
      return "write";
    case "indexer":
      return "indexer";
    default:
      return token;
  }
}

function roleTint(token: string): string {
  switch (token) {
    case "indexer":
      return "rgb(124, 92, 255)";
    case "both":
      return "rgb(46, 194, 126)";
    case "write":
      return "rgb(229, 165, 10)";
    default:
      return "rgb(120, 120, 132)";
  }
}
